INSERT INTO public.deep_cases (id, market_id, day, slot, content, tags) VALUES
($ml$bf39f6cf-e0ca-5866-bfbf-26804e66e970$ml$::uuid, $ml$fintech$ml$, 1, 1, $ml${"id": "fintech-d1-c1", "title": "Billions in PayPal debits stopped", "lessonTitle": "What happens when you pay someone", "slot": 1, "type": "apply", "brief": {"headline": "In late August 2025, German banks blocked PayPal direct debits reportedly worth over €10 billion. PayPal's fraud filter had failed, so unchecked debit requests reached the banks.", "kicker": "Apply day 1: a debit request is a message, not money.", "fullText": "A direct debit is an instruction. PayPal asks a customer's bank to send money from that customer's account. In the week before August 27, 2025, PayPal's system for screening fraudulent transactions was entirely or largely down, the Süddeutsche Zeitung reported, so millions of unverified direct debits reached German banks.\n\nBanks including DZ Bank and BayernLB stopped the payments. The paper put the total at over €10 billion, and a banking source told Reuters that individual amounts ranged from hundreds of millions to billions of euros. Merchants waited for their money while a backlog was cleared. PayPal called it a temporary service outage and said it was resolved.\n\nThrough the day 1 lens: each debit was a message. Until the customer's bank agreed and money actually moved, nothing had settled, and the bank could still say no.", "sources": [{"url": "https://thepaypers.com/fraud-and-fincrime/news/german-banks-halt-eur-10-billion-in-paypal-transactions-over-fraud-reports-newspaper", "label": "The Paypers, German banks halt EUR 10 billion in PayPal transactions, Aug 2025"}, {"url": "https://heise.de/-10622936", "label": "heise online, German banks block PayPal payments, Aug 2025"}, {"url": "https://www.moderntreasury.com/journal/difference-between-settlement-and-clearing", "label": "Modern Treasury, clearing vs settlement"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the PayPal debits. Tap it.", "statements": ["PayPal's fraud screening was down or largely down.", "The debits were requests the banks could still refuse.", "Merchants had already been paid in full."], "fakeIndex": 2, "explanation": "Merchants were still waiting. The debits were instructions, and the banks refused to settle them."}, "numbers": {"kind": "numberSense", "prompt": "The Süddeutsche Zeitung put the blocked debits at over how many billion euros?", "min": 0, "max": 30, "value": 10, "unit": "B", "explanation": "Over €10 billion. Requests that large still needed each bank to agree before any money moved."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a payments operations role at a German bank. They ask what the PayPal episode shows.", "prompt": "Which answer lands best?", "options": ["PayPal lost €10 billion of real money", "Banks must pay every debit they receive", "A debit is an instruction the bank can refuse"], "correctIndex": 2, "consequences": ["No money had moved, so there was nothing to lose yet.", "Banks check debits, and these failed the checks.", "You name the stage the banks used: they declined to settle."], "explanation": "The banks stopped instructions before settlement. Saying that precisely shows you know the stages."}, "proReasoning": "Payments people separate the instruction from the settlement. The banks could stop PayPal because nothing had settled yet.", "commonMistake": "Talking about the debits as if money had already moved.", "mentalModel": "An instruction is not a payment."}, "invest": {"call": {"kind": "theCall", "situation": "You follow PayPal as an investor and read that German banks blocked its debits after its fraud filter failed.", "prompt": "What is the key question?", "options": ["How well PayPal screens what it sends banks", "Whether German shoppers still like PayPal", "Nothing, since no money was ever lost"], "correctIndex": 0, "consequences": ["Banks settle PayPal's debits only while they trust its checks.", "Shoppers matter, but the banks are the ones who said no.", "Lost trust with banks can cost more than one backlog."], "explanation": "PayPal needs banks to settle its debits. Its fraud screening is what keeps them willing."}, "proReasoning": "Investors ask which partner can stop a fintech's money flow. Here, banks held the settlement step.", "commonMistake": "Treating an outage as harmless because the money was recovered.", "mentalModel": "Whoever settles can say no."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup collects monthly fees by direct debit from customers' bank accounts.", "prompt": "When can you count the money as yours?", "options": ["When the customer signs up for the plan", "Once the customer's bank has settled it", "As soon as you send the debit request"], "correctIndex": 1, "consequences": ["A sign-up is a promise, not a payment.", "Settled money is final, and a request can still be refused.", "PayPal sent requests too, and banks blocked billions."], "explanation": "A debit request can be refused until the bank settles it. Plan cash around settlement, not requests."}, "proReasoning": "Founders who collect by debit plan around settled funds. A request that bounces leaves a hole in the cash plan.", "commonMistake": "Booking cash the moment the debit request goes out.", "mentalModel": "Count settled money, not requests."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a bank could refuse payments that PayPal had already sent.", "prompt": "What's the best answer?", "options": ["Banks can claw back any payment at any time", "PayPal forgot to put the money in its account", "PayPal sent requests; no money had moved yet"], "correctIndex": 2, "consequences": ["Settled payments are final, and these never settled.", "PayPal wasn't sending money; it was asking for it.", "A debit asks the bank to send money, and the bank can decline."], "explanation": "PayPal's debits asked banks to pull money from accounts. The banks spotted problems and declined."}, "proReasoning": "Split a payment into its message and its money. Most surprises happen between the two.", "commonMistake": "Thinking a payment moves the moment someone presses send.", "mentalModel": "Message first, money second."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$815ef486-0eb0-5410-a23e-a761cdedb0f8$ml$::uuid, $ml$fintech$ml$, 1, 2, $ml${"id": "fintech-d1-c2", "title": "Instant in the app, days to the bank", "lessonTitle": "What happens when you pay someone", "slot": 2, "type": "connect", "brief": {"headline": "Inside Venmo, a payment updates both balances at once. Moving that money to a bank takes 1 to 3 business days for free, or about 30 minutes for a fee.", "kicker": "Connect two day 1 ideas: an app's ledger and bank settlement.", "fullText": "Day 1 had two ideas that fit together. First, a payment inside Venmo is an entry in Venmo's own records, so both balances change right away. Second, money between banks moves in stages: an instruction, clearing to work out who owes whom, then settlement, when banks move real money between their accounts at one of 12 Reserve Banks.\n\nPut them together. The instant part happens inside one company's ledger. The slow part is the trip between banks. Most apps never settle money themselves; a partner bank with a Fed account does it for them.", "sources": [{"url": "https://help.venmo.com/hc/en-us/articles/235399967-Standard-Bank-Transfers-FAQ", "label": "Venmo, standard bank transfers"}, {"url": "https://www.moderntreasury.com/journal/difference-between-settlement-and-clearing", "label": "Modern Treasury, clearing vs settlement"}, {"url": "https://www.federalreserve.gov/aboutthefed/structure-federal-reserve-system.htm", "label": "Federal Reserve, structure"}, {"url": "https://perkinscoie.com/insights/update/federal-reserve-issues-final-guidelines-master-account-access", "label": "Perkins Coie, Fed master account guidelines"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow your money from the app to your bank.", "steps": ["You tap send in the app", "The app updates both balances in its own records", "You ask to move the money to your bank", "Clearing works out who owes whom", "Banks settle, and the money is final"], "explanation": "The first two steps happen inside one ledger. The rest is the trip between banks."}, "numbers": {"kind": "numberSense", "prompt": "Banks keep accounts at one of how many Reserve Banks?", "min": 0, "max": 40, "value": 12, "explanation": "Twelve. The Fed is the bank for banks, and settlement happens in those accounts."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join Venmo's support team. A user says the app shows the money, but their bank account doesn't.", "prompt": "What do you tell them?", "options": ["The app moved it; the bank trip is still underway", "The payment failed and must be sent again today", "Their bank has lost the money for now"], "correctIndex": 0, "consequences": ["Standard transfers typically take 1 to 3 business days.", "Sending again could pay twice, since the first one worked.", "Nothing is lost; settlement simply takes time."], "explanation": "The in-app balance changed instantly. The transfer to a bank goes through clearing and settlement."}, "proReasoning": "Support teams that know the two trips calm users fast. Say where the money is and when it should land.", "commonMistake": "Treating a normal settlement delay as a failed payment.", "mentalModel": "Name the trip the money is on."}, "invest": {"call": {"kind": "theCall", "situation": "A payments app shows instant transfers, but a partner bank settles every move to outside banks.", "prompt": "What should you check before judging the app?", "options": ["How many users have the app icon", "Which bank it relies on to settle", "How fast the app loads on phones"], "correctIndex": 1, "consequences": ["Users matter, but the bank keeps the money moving.", "The partner bank's health and rules shape the app's business.", "Speed on screen isn't speed between banks."], "explanation": "An app and a bank sit on different layers and earn in different ways. Know which bank is underneath."}, "proReasoning": "Investors find the layer a company sits on before judging it. An app without a Fed account depends on a bank.", "commonMistake": "Assuming the app does the settling because it shows the balance.", "mentalModel": "Find the bank under the app."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're building a wallet app. Users want instant payments to each other.", "prompt": "How do you make that work?", "options": ["Open your own Fed account before launching", "Settle every payment between two banks", "Use your own ledger, with a bank to settle"], "correctIndex": 2, "consequences": ["Most fintechs rely on a partner bank instead.", "That brings back the delay you wanted to avoid.", "Payments between users are ledger entries, and the bank handles exits."], "explanation": "Moves between your own users can be ledger entries. A partner bank settles money in and out."}, "proReasoning": "Founders keep in-app moves on their own books and lean on a partner bank for settlement. That is how apps feel instant.", "commonMistake": "Planning to settle every in-app payment through the banking system.", "mentalModel": "Ledger inside, bank at the edges."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Venmo is instant but moving money to the bank is not.", "prompt": "What's the best answer?", "options": ["In-app is a record change; banks must settle", "Venmo slows transfers to keep your money", "Banks only open on certain weekdays"], "correctIndex": 0, "consequences": ["One ledger changes instantly, and banks move real money in stages.", "The delay comes from clearing and settlement, not Venmo's choice.", "Hours matter, but the stages are the main reason."], "explanation": "Inside Venmo it is one company updating its records. Between banks, clearing and settlement take time."}, "proReasoning": "Ask whose records changed. One company's ledger is instant; moving money between banks is a second trip.", "commonMistake": "Thinking the app balance and the bank balance are the same thing.", "mentalModel": "Your payment makes two trips."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$80fe2cc5-3ecc-5994-96d1-2e7062a16399$ml$::uuid, $ml$fintech$ml$, 1, 3, $ml${"id": "fintech-d1-c3", "title": "Free in days, or paid in minutes", "lessonTitle": "What happens when you pay someone", "slot": 3, "type": "decide", "brief": {"headline": "You run a dog-walking business paid through Venmo. Free transfers to your bank typically take 1 to 3 business days; instant ones take about 30 minutes for a fee.", "kicker": "Decide when settled money is worth paying for.", "fullText": "Venmo's standard transfer to a bank is free and typically arrives within 1 to 3 business days. Its instant transfer costs a fee and typically arrives within 30 minutes.\n\nThe money in your Venmo balance is real in Venmo's records. Until it settles at your bank, you can't pay rent or payroll from it there. The choice is about timing: when do you need settled money, and what is it worth to get it sooner?", "sources": [{"url": "https://help.venmo.com/hc/en-us/articles/235399967-Standard-Bank-Transfers-FAQ", "label": "Venmo, standard bank transfers"}, {"url": "https://www.moderntreasury.com/journal/difference-between-settlement-and-clearing", "label": "Modern Treasury, clearing vs settlement"}]}, "evidence": {"kind": "sortSignal", "prompt": "Has the money settled between banks yet?", "buckets": ["Settled", "Not yet"], "items": [{"text": "Your Venmo balance just updated", "bucket": 1}, {"text": "Clearing has matched the instruction", "bucket": 1}, {"text": "You tapped send a second ago", "bucket": 1}, {"text": "Banks have moved money at the Fed", "bucket": 0}, {"text": "The money is final at your bank", "bucket": 0}], "explanation": "Only the final transfer between banks counts as settlement. Everything before it is a message."}, "numbers": {"kind": "numberSense", "prompt": "Venmo's free standard transfer typically takes up to how many business days?", "min": 0, "max": 10, "value": 3, "unit": "days", "explanation": "Up to 3 business days. The instant option typically takes about 30 minutes, for a fee."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a product analyst at a payments app. Users complain that bank transfers take days.", "prompt": "What do you propose first?", "options": ["Hide the transfer status from users", "Show when each transfer should land", "Promise every transfer is instant"], "correctIndex": 1, "consequences": ["Hiding status makes a normal delay feel like a loss.", "Clear timing cuts worry, since standard transfers take 1 to 3 days.", "Settlement takes time, so the promise would break."], "explanation": "The delay comes from settlement. Showing when money lands sets the right expectation."}, "proReasoning": "Good product people explain a delay they cannot remove. Then they offer a paid fast lane for those who need it.", "commonMistake": "Promising speed the rails underneath cannot deliver.", "mentalModel": "Explain the delay you cannot remove."}, "invest": {"call": {"kind": "theCall", "situation": "A payments app charges a fee for transfers that arrive in about 30 minutes instead of days.", "prompt": "What makes that fee work?", "options": ["Users dislike free products", "The fee makes banks settle faster", "Some users need settled money now"], "correctIndex": 2, "consequences": ["Most users choose free; the fee serves those in a hurry.", "The app pays for speed; the bank's stages still exist.", "Rent, payroll and bills need money at the bank, not in the app."], "explanation": "The fee sells time. It works because settled money matters more to some users on some days."}, "proReasoning": "Investors look for fees people pay willingly. Paying to get settled money sooner is one of them.", "commonMistake": "Assuming any fee on a free product drives users away.", "mentalModel": "Speed is something people buy."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the dog-walking business. Payroll is due Friday morning, and it is Thursday afternoon.", "prompt": "How do you move the money?", "options": ["Pay the fee for an instant transfer", "Use the free transfer and hope it lands", "Pay staff in Venmo IOUs for now"], "correctIndex": 0, "consequences": ["About 30 minutes means payroll is covered, at a small cost.", "Up to 3 business days could miss Friday.", "Staff need settled money, not promises."], "explanation": "When a deadline needs settled money, a fee for speed can be cheaper than missing it."}, "proReasoning": "Founders match payment speed to the deadline. Pay for instant when it matters, and use free when it does not.", "commonMistake": "Always choosing free and then missing a payment that matters.", "mentalModel": "Match speed to the deadline."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why anyone pays for instant transfer when the standard one is free.", "prompt": "What's the best answer?", "options": ["The free one sometimes never arrives", "They need the money settled today", "Instant transfers send more money"], "correctIndex": 1, "consequences": ["Standard transfers arrive, just more slowly.", "The fee buys about 30 minutes instead of up to 3 days.", "The amount is the same; only the timing differs."], "explanation": "Both move the same money. The fee pays for getting it settled at your bank much sooner."}, "proReasoning": "When two options move the same thing, the price difference is usually about time.", "commonMistake": "Thinking the paid option moves something different.", "mentalModel": "The fee buys time."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$ee6ab16c-3f26-5155-9272-6f0245688110$ml$::uuid, $ml$fintech$ml$, 2, 1, $ml${"id": "fintech-d2-c1", "title": "The $5 overdraft cap that never came", "lessonTitle": "How a bank makes money", "slot": 1, "type": "apply", "brief": {"headline": "In December 2024, the CFPB capped overdraft fees at $5 for banks with over $10 billion in assets. Congress overturned the rule, and the president signed the repeal on May 9, 2025.", "kicker": "Apply day 2: fees are a bank's second engine.", "fullText": "The rule was due to take effect in October 2025. Large banks and credit unions could charge $5, charge a fee that covered their costs and losses, or keep current fees if they gave card-style disclosures. Some lenders still charged around $35 per overdraft. The CFPB argued the rule could cut institutions' overdraft fee revenue by $5 billion a year. Bank groups sued within a day of the rule's release, saying the bureau had exceeded its authority.\n\nThrough the day 2 lens: overdraft fees are noninterest income. They don't depend on the gap between deposit and loan rates, which is part of why banks fought to keep them.", "sources": [{"url": "https://www.bankingdive.com/news/trump-sign-overturn-cfpb-overdraft-cap-rule-scott-hill-aba-lawsuit-5-dollars/747727/", "label": "Banking Dive, Trump signs repeal of CFPB overdraft rule, May 2025"}, {"url": "https://www.fdic.gov/quarterly-banking-profile/statistics-glance-industry-trends-fourth-quarter-2025.pdf", "label": "FDIC, industry at a glance Q4 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "A $5 overdraft cap would cut which kind of bank income?", "options": ["Net interest income from loans", "Interest earned on Fed reserves", "Noninterest income from fees"], "correctIndex": 2, "explanation": "Overdraft fees are fee income. They sit beside the rate gap, not inside it."}, "numbers": {"kind": "numberSense", "prompt": "Some lenders charged about $35 per overdraft. What share of that would a $5 cap remove?", "min": 0, "max": 100, "value": 86, "unit": "%", "explanation": "Cutting $35 to $5 removes $30, about 86%. That is why the cap mattered so much to fee income."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a large bank in mid-2025. They ask what the overdraft repeal means for the business.", "prompt": "What's your best answer?", "options": ["It protects fee income not tied to rates", "It raises the bank's margin on mortgages", "It caps overdraft fees at $5 from now on"], "correctIndex": 0, "consequences": ["You place overdraft fees on the right side of the income statement.", "Mortgage margins come from the rate gap, not overdrafts.", "The repeal removed the $5 cap before it took effect."], "explanation": "The repeal kept a stream of noninterest income in place. Knowing which engine it feeds shows you read banks well."}, "proReasoning": "Strong candidates sort a bank into its two engines, interest and fees, then say which one a headline touches.", "commonMistake": "Mixing up fee income with the rate gap.", "mentalModel": "Ask which engine the news touches."}, "invest": {"call": {"kind": "theCall", "situation": "Two banks have similar loan books. One earns far more from overdraft fees than the other.", "prompt": "Which had more riding on the repeal?", "options": ["Neither, since fees are a small detail", "The bank leaning more on overdraft fees", "The bank with more mortgage loans"], "correctIndex": 1, "consequences": ["The CFPB put the stake at $5 billion a year.", "A cap would have hit its noninterest income hardest.", "Mortgages earn the rate gap, which the rule left alone."], "explanation": "The rule targeted fee income. The more a bank relied on overdrafts, the more it had at stake."}, "proReasoning": "Investors split a bank's income by source before judging a rule. A fee cap hits fee-heavy banks hardest.", "commonMistake": "Judging a fee rule by loan size instead of fee reliance.", "mentalModel": "Find which income a rule touches."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your app gives users small advances so they can avoid bank overdraft fees.", "prompt": "What does the repeal mean for you?", "options": ["Overdraft fees are now capped at $5 a time", "Banks will soon drop overdrafts entirely", "Banks keep charging, so your problem stays"], "correctIndex": 2, "consequences": ["The cap was repealed before it took effect.", "Banks fought to keep overdraft income, not to drop it.", "Fees of around $35 at some lenders keep your pitch alive."], "explanation": "A rule that would have shrunk the fee is gone. The problem your app solves is still there."}, "proReasoning": "Founders track rules that could erase the pain they solve. A repeal can keep a market open.", "commonMistake": "Assuming a proposed rule is final before it takes effect.", "mentalModel": "Watch the rule that could erase your pain."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why banks fought so hard over a $5 cap on overdraft fees.", "prompt": "What's the best answer?", "options": ["Fees bring income without lending anything", "Overdrafts are the main way banks lend", "The cap would have closed small banks"], "correctIndex": 0, "consequences": ["Fee income adds to the rate gap, and the CFPB put it at $5 billion a year.", "Lending earns interest; overdraft fees are charged per event.", "The rule only covered banks over $10 billion in assets."], "explanation": "Banks earn in two ways: the rate gap and fees. Overdraft fees were a large fee stream at stake."}, "proReasoning": "Explain a bank as two engines: the rate gap and fees. Fights over fees are fights over the second engine.", "commonMistake": "Thinking banks only earn from interest.", "mentalModel": "Banks run on two engines."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$82d868c8-f9c2-5826-b96f-d36964b8f524$ml$::uuid, $ml$fintech$ml$, 2, 2, $ml${"id": "fintech-d2-c2", "title": "The account that pays the bank", "lessonTitle": "How a bank makes money", "slot": 2, "type": "connect", "brief": {"headline": "Banks keep accounts at one of 12 Reserve Banks so they can settle payments. The Fed also pays interest on the reserves banks hold there.", "kicker": "Connect day 1 and day 2: the Fed account also earns money.", "fullText": "On day 1 you met the Fed as the bank for banks. Each bank keeps an account at one of 12 Reserve Banks, and payments settle between those accounts.\n\nOn day 2 you saw how banks earn: the gap between what money costs and what it earns, plus fees. The Fed account sits in both stories. It is where settlement happens, and the reserves held there earn interest. That interest counts as interest income, beside loans and bonds.", "sources": [{"url": "https://www.federalreserve.gov/aboutthefed/structure-federal-reserve-system.htm", "label": "Federal Reserve, structure"}, {"url": "https://www.federalreserve.gov/monetarypolicy/reserve-balances.htm", "label": "Federal Reserve, interest on reserve balances"}, {"url": "https://www.fdic.gov/news/press-releases/2026/fdic-insured-institutions-reported-return-assets-124-percent-and-net", "label": "FDIC, Q4 2025 banking profile"}]}, "evidence": {"kind": "faceOff", "prompt": "A bank leaves spare cash in its Fed account overnight. What kind of income does it earn?", "left": {"name": "Interest income", "note": "Like loan and bond interest"}, "right": {"name": "Fee income", "note": "Like card and account fees"}, "correctIndex": 0, "explanation": "Interest on reserves is interest income. It is part of what a bank earns on its assets."}, "numbers": {"kind": "numberSense", "prompt": "About how many thousand FDIC-insured banks hold the public's deposits?", "min": 0, "max": 10, "value": 4.3, "unit": "K", "explanation": "About 4,300. Each settles through a Fed account, its own or a partner bank's."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a new analyst on a bank's treasury desk. Your boss asks why the bank keeps reserves at the Fed.", "prompt": "What's your answer?", "options": ["To earn fees from the Fed each month", "To settle payments, and they earn interest", "Only because the law requires 10%"], "correctIndex": 1, "consequences": ["The Fed pays interest on reserves, not fees.", "You cover both roles of the account: settlement and income.", "US banks face no 10% reserve rule today."], "explanation": "The Fed account is where payments settle, and the balance earns interest. Both matter to treasury."}, "proReasoning": "Treasury people see reserves as a tool for settlement and a source of interest income. Say both.", "commonMistake": "Calling reserves dead money.", "mentalModel": "Reserves settle payments and earn interest."}, "invest": {"call": {"kind": "theCall", "situation": "The Fed cuts the rate it pays on reserves. A bank leaves its savings rates unchanged for now.", "prompt": "What happens to its margin for now?", "options": ["It widens, since it pays the same", "Nothing, since reserves earn no interest", "It narrows until deposit rates follow"], "correctIndex": 2, "consequences": ["It earns less on reserves while paying savers the same.", "Reserves do earn interest, so the cut bites.", "Asset income fell first, while deposit costs stayed put."], "explanation": "Each side of the balance sheet reprices at its own speed. The lag moves the margin."}, "proReasoning": "Investors watch which side reprices first. A cut that hits asset income before deposit costs narrows the margin.", "commonMistake": "Assuming both sides of the margin move together.", "mentalModel": "Watch which side reprices first."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your fintech's customer cash sits at a partner bank, which holds the Fed account.", "prompt": "Who earns the interest on those reserves?", "options": ["The bank, so any share is up to your deal", "Your fintech, since the customers are yours", "Your customers, directly from the Fed"], "correctIndex": 0, "consequences": ["The account holder earns it, and your contract decides any share.", "The Fed pays the bank that holds the account.", "Customers earn whatever their account pays, not Fed interest."], "explanation": "The Fed pays the bank that holds the reserves. What reaches you depends on your agreement."}, "proReasoning": "Founders read the economics in the bank deal. Interest on customer cash is earned by whoever holds the Fed account.", "commonMistake": "Assuming customer cash earns money for the app by default.", "mentalModel": "Interest follows the account holder."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether banks have bank accounts of their own.", "prompt": "What's the best answer?", "options": ["Yes, at other banks, never at the Fed", "Yes, at the Fed, which pays them interest", "No, banks keep all their cash in vaults"], "correctIndex": 1, "consequences": ["Some use partner banks, but the Fed is the bank for banks.", "Banks hold accounts at one of 12 Reserve Banks.", "Banks settle payments between Fed accounts, not with vault cash."], "explanation": "The Fed is the bank for banks. Their accounts there settle payments and earn interest."}, "proReasoning": "Picture the Fed as the bank where banks keep their own accounts. That explains settlement and interest on reserves.", "commonMistake": "Thinking a bank's money is all cash in a vault.", "mentalModel": "The Fed is the bank for banks."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$20635420-f12a-5337-a0d6-8269c95c6938$ml$::uuid, $ml$fintech$ml$, 2, 3, $ml${"id": "fintech-d2-c3", "title": "Price the savings account", "lessonTitle": "How a bank makes money", "slot": 3, "type": "decide", "brief": {"headline": "In October 2026, the average US savings account paid 0.38% and the average 30-year mortgage cost 7.40%. The FDIC put the industry's net interest margin at 3.39% in late 2025.", "kicker": "Decide how to price deposits without losing the gap.", "fullText": "A bank takes in deposits at one rate and lends or invests them at another. The FDIC's national average savings rate was 0.38% in October 2026; Freddie Mac's average 30-year fixed mortgage was 7.40% in mid-October. Across the industry, net interest margin, interest earned minus interest paid as a share of earning assets, was 3.39%. FDIC-insured banks earned $295.6 billion in net income in 2025.\n\nYou run a small community bank. An online rival pays far more on savings, and some customers ask you to match it.", "sources": [{"url": "https://fred.stlouisfed.org/series/SNDR", "label": "FDIC national savings rate (FRED)"}, {"url": "https://www.freddiemac.com/pmms", "label": "Freddie Mac mortgage survey"}, {"url": "https://www.fdic.gov/news/press-releases/2026/fdic-insured-institutions-reported-return-assets-124-percent-and-net", "label": "FDIC, Q4 2025 banking profile"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each move widen or narrow your rate gap?", "buckets": ["Widens the gap", "Narrows the gap"], "items": [{"text": "Charging more on new loans", "bucket": 0}, {"text": "Paying less on deposits", "bucket": 0}, {"text": "Raising your savings rate", "bucket": 1}, {"text": "Loan rates falling after rate cuts", "bucket": 1}, {"text": "Matching a rival that pays more", "bucket": 1}], "explanation": "The margin is what you earn minus what you pay. Anything that raises your costs or cuts your yields narrows it."}, "numbers": {"kind": "numberSense", "prompt": "At a 3.39% margin, how many dollars a year does a bank net on $10,000 of earning assets?", "min": 0, "max": 1000, "value": 339, "unit": "$", "explanation": "About $339, before costs and losses. Across trillions in assets, that gap is the business."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a community bank. They ask how you'd judge their net interest margin.", "prompt": "What do you do first?", "options": ["Compare it with the 7.40% mortgage rate", "Ignore it and focus on branch count", "Compare it with the industry's 3.39%"], "correctIndex": 2, "consequences": ["A mortgage rate is one yield, not a margin.", "The margin is the core of how the bank earns.", "A benchmark turns one number into a view."], "explanation": "The industry margin gives you a yardstick. Above or below it says something real about the bank."}, "proReasoning": "Bring a benchmark to every bank number. Margin against the industry average starts a real conversation.", "commonMistake": "Comparing a margin with a single rate.", "mentalModel": "Every number needs a yardstick."}, "invest": {"call": {"kind": "theCall", "situation": "A bank raises its savings rate to stop deposits leaving for an online rival.", "prompt": "What do you watch next?", "options": ["Whether loan yields keep the gap intact", "Whether the bank opens more branches", "Whether savers praise the new rate"], "correctIndex": 0, "consequences": ["Higher deposit costs squeeze the margin unless yields keep up.", "Branches don't fix a squeezed margin.", "Praise doesn't pay; the margin does."], "explanation": "Paying more for deposits narrows the margin. The question is whether asset yields keep pace."}, "proReasoning": "Investors treat a deposit rate rise as a cost. They check whether the asset side can absorb it.", "commonMistake": "Cheering deposit growth without checking what it cost.", "mentalModel": "Deposits have a price."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the community bank. Some customers ask you to match an online rival that pays far more on savings.", "prompt": "What do you weigh?", "options": ["Only the 7.40% average mortgage rate", "Deposits kept against a thinner margin", "Only what the online rival pays savers"], "correctIndex": 1, "consequences": ["Mortgage rates set one side; deposit costs set the other.", "Matching keeps funding but costs part of your gap.", "The rival's rate is one input, not the whole decision."], "explanation": "Every point you pay savers comes out of your margin. Weigh it against the cost of losing deposits."}, "proReasoning": "Bankers price deposits against the margin they need. Losing deposits has a cost, and so does paying too much.", "commonMistake": "Matching a rival's rate without checking the margin.", "mentalModel": "Price deposits against your margin."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a bank profits if it pays only 0.38% on savings.", "prompt": "What's the best answer?", "options": ["It charges savers to hold their money", "The government pays it to take deposits", "It lends savings out at higher rates"], "correctIndex": 2, "consequences": ["Fees exist, but the rate gap is the core.", "Banks earn on reserves, but deposits aren't paid for by the state.", "A mortgage near 7.40% against savings at 0.38% is the gap."], "explanation": "Your savings are raw material. The bank lends or invests them at a higher rate and keeps the gap."}, "proReasoning": "Explain a bank with two numbers: what it pays you and what it charges a borrower. The gap is its pay.", "commonMistake": "Thinking the bank simply stores your money.", "mentalModel": "A bank earns the gap."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$0be5d99a-1118-5a3e-a2dc-62d0c89ff18c$ml$::uuid, $ml$fintech$ml$, 3, 1, $ml${"id": "fintech-d3-c1", "title": "Kraken's key, Custodia's locked door", "lessonTitle": "Who gets a key to the Fed", "slot": 1, "type": "apply", "brief": {"headline": "On March 4, 2026, the Kansas City Fed gave Kraken Financial a limited account with direct Fedwire access. Custodia Bank, refused a master account, lost again in court that month.", "kicker": "Apply day 3: the Fed decides who gets a key, and what it opens.", "fullText": "Kraken Financial, the Wyoming banking arm of crypto exchange Kraken, got a limited-purpose account from the Federal Reserve Bank of Kansas City for an initial one-year term. It can settle directly on Fedwire, cutting its reliance on correspondent banks. It cannot earn interest on reserves or borrow from the Fed in an emergency, has no access to FedNow or ACH, and may hold only limited balances overnight.\n\nCustodia, another Wyoming crypto bank, sued the Fed in 2022 seeking a master account, which was refused. In October 2025, a Tenth Circuit panel ruled that Reserve Banks have discretion over master accounts. In March 2026, the full court declined to rehear the case, 7 votes to 3; the majority noted Custodia could still reach the rails through a correspondent bank.", "sources": [{"url": "https://cointelegraph.com/news/kraken-crypto-exchange-fed-master-account", "label": "Cointelegraph, Kraken gets a Fed master account, Mar 2026"}, {"url": "https://www.pymnts.com/cryptocurrency/2026/kraken-reveals-fed-account-bars-interest-and-emergency-lending/", "label": "PYMNTS, Kraken's Fed account bars interest and emergency lending, Apr 2026"}, {"url": "https://www.bankingdive.com/news/custodia-fed-master-account-rehearing-denied-petition-supreme-court-skinny-kraken/815086/", "label": "Banking Dive, Custodia denied rehearing over Fed master account, Mar 2026"}, {"url": "https://perkinscoie.com/insights/update/federal-reserve-issues-final-guidelines-master-account-access", "label": "Perkins Coie, Fed master account guidelines"}]}, "evidence": {"kind": "sortSignal", "prompt": "What did Kraken's limited Fed account include?", "buckets": ["Included", "Not included"], "items": [{"text": "Direct access to Fedwire", "bucket": 0}, {"text": "Limited balances held overnight", "bucket": 0}, {"text": "Interest on reserves", "bucket": 1}, {"text": "Emergency loans from the Fed", "bucket": 1}, {"text": "Access to FedNow and ACH", "bucket": 1}], "explanation": "Kraken got a narrow key: Fedwire settlement, without interest, emergency lending or the other rails."}, "numbers": {"kind": "numberSense", "prompt": "Of the ten judges voting, how many declined to rehear Custodia's case?", "min": 0, "max": 10, "value": 7, "explanation": "Seven to three. The Fed kept its discretion over who gets a master account."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at Kraken in 2026. They ask what the new Fed account changes.", "prompt": "What's your best answer?", "options": ["It now earns interest on its reserves", "It settles on Fedwire without a middle bank", "It can now borrow from the Fed in a pinch"], "correctIndex": 1, "consequences": ["Interest on reserves was barred too.", "That is the core gain: less reliance on correspondent banks.", "Emergency Fed lending was specifically left out."], "explanation": "The account opens Fedwire and little else. Knowing its limits shows you read the details."}, "proReasoning": "Describe a new license by what it opens and what it leaves shut. Precision beats hype in an interview.", "commonMistake": "Calling a limited account a full bank account at the Fed.", "mentalModel": "Say what the key opens, and what it does not."}, "invest": {"call": {"kind": "theCall", "situation": "A crypto firm gets direct Fedwire access, but no interest on reserves, emergency loans or ACH.", "prompt": "How do you read it?", "options": ["A full bank charter in all but name", "Meaningless, since it lacks FedNow", "A real but narrow key: fewer middlemen"], "correctIndex": 2, "consequences": ["It lacks interest, lending and most rails a bank has.", "Fedwire access alone changes how it settles.", "Direct settlement cuts reliance on partners, within tight limits."], "explanation": "Direct Fedwire settlement matters. The limits show the Fed decides how far access goes."}, "proReasoning": "Investors size a regulatory win by its limits. A one-year, Fedwire-only account is progress, not a bank's full toolkit.", "commonMistake": "Reading a narrow approval as a full license.", "mentalModel": "Size the win by its limits."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your payments startup wants a Fed account like Kraken's. Custodia was refused one and lost in court.", "prompt": "What do you plan around?", "options": ["The Fed's discretion; keep a partner bank too", "A legal right to an account if you go to court", "Fast approval as soon as you file"], "correctIndex": 0, "consequences": ["Courts upheld the Fed's discretion, so a bank partner stays essential.", "The Tenth Circuit ruled there is no automatic right.", "Custodia waited years and still lost."], "explanation": "The Fed chooses who gets access. Build so your business works through a partner bank either way."}, "proReasoning": "Founders treat Fed access as an option, not a plan. The partner bank route keeps the business running meanwhile.", "commonMistake": "Betting the company on getting a master account.", "mentalModel": "Plan for the Fed to say no."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why the Fed can refuse an account to a Wyoming bank.", "prompt": "What's the best answer?", "options": ["Crypto firms are banned from the Fed", "Courts said Reserve Banks have discretion", "Only giant banks may legally have one"], "correctIndex": 1, "consequences": ["Kraken, a crypto firm, got a limited account in 2026.", "The Tenth Circuit backed the Fed's choice in Custodia's case.", "Size is not the test; the Fed weighs each request."], "explanation": "The courts found Reserve Banks have discretion over master accounts. Kraken shows the answer can be a limited yes."}, "proReasoning": "Access to the Fed is a decision, not a right. That is where power in banking sits.", "commonMistake": "Thinking any licensed bank automatically gets a Fed account.", "mentalModel": "Fed access is granted, not owed."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$b0302f11-1c81-59a3-b3f9-fc5789359069$ml$::uuid, $ml$fintech$ml$, 3, 2, $ml${"id": "fintech-d3-c2", "title": "Whose ledger is right?", "lessonTitle": "Who gets a key to the Fed", "slot": 2, "type": "connect", "brief": {"headline": "Inside an app, a balance is an entry in someone's records. At Synapse, those records stopped matching the banks' records as early as September 2023.", "kicker": "Connect day 1 and day 3: who keeps the record of who owns what?", "fullText": "On day 1 you saw that a payment inside an app is an entry in the app's own records. On day 3 you met Synapse, a middleman between apps such as Yotta and Juno and the banks that held the money. The banks held pooled deposits; Synapse kept the records of who owned which dollars.\n\nThose records stopped matching the banks' records as early as September 2023. After Synapse filed for bankruptcy in April 2024, partner banks found a shortfall of between $60 million and $90 million. In August 2025 the CFPB sued Synapse, alleging it failed to keep proper track of consumers' funds.", "sources": [{"url": "https://help.venmo.com/hc/en-us/articles/235399967-Standard-Bank-Transfers-FAQ", "label": "Venmo, standard bank transfers"}, {"url": "https://www.bankingdive.com/news/cfpb-sues-synapse-plans-use-victims-fund-pay-end-users/758776/", "label": "Banking Dive on the Synapse suit"}, {"url": "https://www.consumerfinancemonitor.com/2025/08/29/cfpb-files-complaint-against-synapse-financial-technologies/", "label": "Consumer Finance Monitor on the CFPB complaint"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how a records gap becomes a shortfall.", "steps": ["An app shows balances from a middleman", "The middleman tracks who owns which dollars", "Partner banks hold the pooled money", "The records drift from the banks' records", "The middleman fails and a shortfall appears"], "explanation": "The money sat at banks, but the record of ownership lived elsewhere. When it broke, users could not prove what was theirs."}, "numbers": {"kind": "numberSense", "prompt": "Partner banks found a shortfall of up to how many million dollars?", "min": 0, "max": 200, "value": 90, "unit": "M", "explanation": "Between $60 million and $90 million. Many customers did not get their full balances."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a fintech's finance team. The app's balances and the bank's records differ a little each day.", "prompt": "What do you do?", "options": ["Ignore it, since the amounts are small", "Adjust the app to match the bank silently", "Reconcile daily and escalate the gap"], "correctIndex": 2, "consequences": ["Small daily gaps added up at Synapse.", "Silent fixes hide the cause and the owner of each dollar.", "Small gaps grow; Synapse's records drifted for months."], "explanation": "Reconciliation is how you keep two ledgers honest. Gaps need a cause, not a patch."}, "proReasoning": "Finance teams treat any mismatch between app and bank as urgent. Synapse showed how drift becomes a shortfall.", "commonMistake": "Letting small reconciliation gaps ride.", "mentalModel": "Two ledgers must agree every day."}, "invest": {"call": {"kind": "theCall", "situation": "A fintech's user balances live in a middleman's ledger, not at the bank.", "prompt": "What do you check?", "options": ["Who keeps the records and how they reconcile", "How many users the app has signed up so far", "How fast the app moves money in and out"], "correctIndex": 0, "consequences": ["At Synapse, records failed and money froze.", "User growth is no help if ownership records fail.", "Speed matters less than knowing who owns what."], "explanation": "The risk sits in the records. If they fail, users may not get their money back in full."}, "proReasoning": "Investors trace who holds the money and who holds the record. When those differ, the record is a risk.", "commonMistake": "Assuming money at a bank is safe whatever the records say.", "mentalModel": "Money needs a reliable record of ownership."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're choosing how your app will hold users' money at a bank.", "prompt": "What matters most in the setup?", "options": ["Pooling all funds with no user records", "The bank can see who owns each dollar", "The cheapest middleman on the market"], "correctIndex": 1, "consequences": ["Without records, no one can prove whose money is whose.", "If anything fails, the bank can still pay each user.", "Synapse showed what weak records can cost users."], "explanation": "Users are safe only if someone can show what each one owns. Build that into the setup from day one."}, "proReasoning": "Founders design for failure: if the middle layer vanished, could the bank still pay every user?", "commonMistake": "Choosing a setup on price alone.", "mentalModel": "Design for the day the middle fails."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how Synapse users lost money if the banks still had deposits.", "prompt": "What's the best answer?", "options": ["The banks spent the deposits", "The users sent money to scammers", "The records of who owned what broke"], "correctIndex": 2, "consequences": ["The CFPB pointed to Synapse's records, not the banks spending.", "This was a records failure, not a scam.", "Without reliable records, banks couldn't match money to people."], "explanation": "The CFPB alleged Synapse failed to track consumer funds. Money without a reliable owner record is hard to return."}, "proReasoning": "Owning money means someone keeps a correct record of it. Break the record and the money gets stuck.", "commonMistake": "Thinking money at a bank is safe no matter who keeps the books.", "mentalModel": "Your balance is only as good as the record."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$19747c72-840b-5529-b10a-c065f2a389d1$ml$::uuid, $ml$fintech$ml$, 3, 3, $ml${"id": "fintech-d3-c3", "title": "Who holds the key in your app?", "lessonTitle": "Who gets a key to the Fed", "slot": 3, "type": "decide", "brief": {"headline": "You run a savings app with no bank license. A bank with a Fed master account can settle on Fedwire directly; your app cannot.", "kicker": "Decide how to work with the bank that holds your app's key.", "fullText": "A master account at the Fed gives direct access to its payment systems, like Fedwire. Without one, a fintech relies on a partner bank to hold deposits and reach the rails. Banks vary hugely in size: JPMorgan Chase Bank alone held $4.1 trillion in assets in mid-2026.\n\nIn banking, power sits with whoever holds the license and the Fed account. Your partner bank's rules and appetite set the limits of what your app can do.", "sources": [{"url": "https://perkinscoie.com/insights/update/federal-reserve-issues-final-guidelines-master-account-access", "label": "Perkins Coie, Fed master account guidelines"}, {"url": "https://www.federalreserve.gov/releases/lbr/current/default.htm", "label": "Federal Reserve, large commercial banks"}, {"url": "https://www.consumerfinancemonitor.com/2025/08/29/cfpb-files-complaint-against-synapse-financial-technologies/", "label": "Consumer Finance Monitor on the CFPB complaint"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Your app has no master account. How does a user payment reach Fedwire?", "options": ["Through your partner bank's account", "Directly, through your app's servers", "It cannot reach Fedwire at all"], "correctIndex": 0, "explanation": "Fintechs without a master account plug in through a partner bank, which holds the key."}, "numbers": {"kind": "numberSense", "prompt": "JPMorgan Chase Bank held about how many trillion dollars in assets in mid-2026?", "min": 0, "max": 10, "value": 4.1, "unit": "T", "explanation": "About $4.1 trillion. Banks with Fed accounts range from giants like this to small community banks."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a fintech with no bank charter. You get to ask one question.", "prompt": "What do you ask?", "options": ["Which bank holds deposits, and how do records match?", "What's the team's favorite feature in the app?", "How many downloads did the app get last year?"], "correctIndex": 0, "consequences": ["After Synapse, that question shows you know where risk sits.", "Friendly, but it says nothing about how money moves.", "Downloads say little about whose license you depend on."], "explanation": "The partner bank holds the license and the deposits. Asking about it shows you see the power structure."}, "proReasoning": "Ask who holds the money and how records are reconciled. It signals you understand fintech after Synapse.", "commonMistake": "Asking only about product and growth.", "mentalModel": "Ask who holds the money."}, "invest": {"call": {"kind": "theCall", "situation": "A fintech's partner bank decides to cut back on fintech clients.", "prompt": "What happens to the fintech?", "options": ["It settles directly with the Fed instead", "It must adapt or find a new bank", "Nothing, since the users belong to it"], "correctIndex": 1, "consequences": ["Without a master account, it has no direct route.", "The bank holds the license, so its appetite sets the limits.", "Users need the bank behind the app to move money."], "explanation": "The fintech rents its access. When the landlord changes the terms, the tenant adjusts."}, "proReasoning": "Investors count the partner bank as part of a fintech's risk. Its appetite can change the fintech's plans overnight.", "commonMistake": "Treating the partner bank as a supplier that's easy to swap.", "mentalModel": "Rented access can be withdrawn."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the savings app. Your partner bank asks for daily records of who owns each dollar.", "prompt": "How do you respond?", "options": ["Refuse, since the users are yours", "Switch to a bank that asks less", "Build it; the bank holds the license"], "correctIndex": 2, "consequences": ["Without the bank, your users cannot move money at all.", "Banks asking less is how records failed at Synapse.", "Meeting the bank's rules keeps your access to the rails."], "explanation": "The bank's license is your access. Clean daily records protect your users and your partnership."}, "proReasoning": "Founders build to their partner bank's standards early. It is cheaper than losing the bank later.", "commonMistake": "Treating the bank's requests as red tape.", "mentalModel": "Your bank's rules are your rules."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says their savings app is a bank.", "prompt": "How can they check?", "options": ["Look in the fine print for the bank's name", "Check how modern and polished the app looks", "Ask the app's chatbot whether it's a bank"], "correctIndex": 0, "consequences": ["The fine print usually names the bank that holds the money.", "Design says nothing about the license.", "A chatbot is no substitute for the legal terms."], "explanation": "Many money apps are not banks. The bank that holds the money is named in the terms."}, "proReasoning": "Find the licensed bank behind any money app. It holds the deposits and the key to the rails.", "commonMistake": "Assuming an app that looks like a bank is one.", "mentalModel": "Find the bank in the fine print."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$1358a1c3-26f2-5641-8936-82be1b307461$ml$::uuid, $ml$fintech$ml$, 4, 1, $ml${"id": "fintech-d4-c1", "title": "Visa's $52 average", "lessonTitle": "The numbers behind the plumbing", "slot": 1, "type": "apply", "brief": {"headline": "In fiscal 2025, Visa processed 257.5 billion transactions. Worldwide, Visa-brand cards carried $17 trillion of payments and cash across 329 billion transactions, about $52 each.", "kicker": "Apply day 4: divide value by count to see who uses a rail.", "fullText": "Visa's fiscal year ended September 30, 2025. Its own network processed 257.5 billion transactions, up 10%, or about 901 million a day. Counting all payments and cash with Visa's brand, including some processed by other networks, the total was 329 billion transactions and $17 trillion. Visa had nearly 5 billion payment credentials usable at more than 175 million merchant locations.\n\nUse the day 4 tool. $17 trillion over 329 billion is about $52 a transaction. Compare ACH at about $2,600 and Fedwire at about $5.3 million. Small averages point to everyday purchases; huge ones point to transfers between big institutions.", "sources": [{"url": "https://www.sec.gov/Archives/edgar/data/1403161/000140316125000089/v-20250930.htm", "label": "Visa, Form 10-K for fiscal 2025"}, {"url": "https://www.sec.gov/Archives/edgar/data/1403161/000140316125000077/q42025earningsrelease.htm", "label": "Visa, fiscal Q4 2025 earnings release, Oct 2025"}, {"url": "https://www.nacha.org/news/same-day-ach-and-business-business-payments-propel-ach-network-volume-growth-2025", "label": "Nacha, ACH volume 2025"}, {"url": "https://frbservices.org/resources/financial-services/wires/volume-value-stats/annual-stats.html", "label": "Fedwire annual statistics"}]}, "evidence": {"kind": "faceOff", "prompt": "Which rail carries the bigger average payment?", "left": {"name": "Visa cards", "note": "$17 trillion over 329 billion transactions"}, "right": {"name": "ACH", "note": "$93 trillion over 35.2 billion payments"}, "correctIndex": 1, "explanation": "ACH averages about $2,600 a payment; Visa about $52. Cards carry the count, not the size."}, "numbers": {"kind": "numberSense", "prompt": "$17 trillion over 329 billion transactions is about how many dollars each?", "min": 0, "max": 200, "value": 52, "unit": "$", "explanation": "About $52, against $2,600 on ACH and $5.3 million on Fedwire."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at Visa. They ask what one number tells you about the network.", "prompt": "What's your best answer?", "options": ["It moves more value each year than Fedwire", "It moves more money each year than ACH", "About $52 a transaction: everyday spending"], "correctIndex": 2, "consequences": ["Fedwire moves about $4.6 trillion a day, far more value.", "ACH moved $93 trillion in 2025, far more value.", "Average size tells them you know who uses the rail."], "explanation": "Dividing value by count shows the rail serves huge numbers of small payments."}, "proReasoning": "Turn two big numbers into one telling one. Average ticket size explains a network in a sentence.", "commonMistake": "Quoting Visa's size without saying what kind of payments it carries.", "mentalModel": "Value over count tells the story."}, "invest": {"call": {"kind": "theCall", "situation": "A friend says Visa is small next to ACH, which moved $93 trillion in 2025.", "prompt": "How should you compare them?", "options": ["By count and what each earns per payment", "By total value moved, nothing else", "By how many years each has existed"], "correctIndex": 0, "consequences": ["Visa processed 257.5 billion transactions; value alone misses that.", "Value favors big transfers and hides the count.", "Age says little about who uses a rail."], "explanation": "Rails differ in what they carry. Count and pricing matter as much as total value."}, "proReasoning": "Investors compare rails on count, size and pricing together. Value alone favors rails built for big transfers.", "commonMistake": "Ranking payment networks by total value moved.", "mentalModel": "Count and value tell different stories."}, "build_startup": {"call": {"kind": "theCall", "situation": "You plan to charge $1 per payment for a new checkout product.", "prompt": "On which rail is that fee easiest to bear?", "options": ["Both, since the fee is the same", "ACH, averaging about $2,600", "Cards, averaging about $52"], "correctIndex": 1, "consequences": ["The same fee weighs very differently by ticket size.", "$1 on $2,600 is tiny; on $52 it is about 2%.", "On a $52 average, $1 is a big slice."], "explanation": "A flat fee matters relative to the payment. Average size tells you how it will feel."}, "proReasoning": "Founders test a fee against the average ticket on each rail. A flat fee that is fine on ACH can sting on cards.", "commonMistake": "Pricing without checking the average payment size.", "mentalModel": "Price against the average ticket."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how many transactions 257.5 billion a year really is.", "prompt": "What does it come to per day?", "options": ["About 9 million a day", "About 90 billion a day", "About 900 million a day"], "correctIndex": 2, "consequences": ["That is a hundred times too small.", "That is a hundred times too large.", "Visa put it at about 901 million a day."], "explanation": "Visa processed about 901 million transactions a day across its network."}, "proReasoning": "Break a yearly number into a daily one. It makes huge counts easier to feel.", "commonMistake": "Leaving a giant number as an abstraction.", "mentalModel": "Turn yearly into daily."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$1baa91a8-1a06-5b8e-9a35-651ed40e987e$ml$::uuid, $ml$fintech$ml$, 4, 2, $ml${"id": "fintech-d4-c2", "title": "Where the big money settles", "lessonTitle": "The numbers behind the plumbing", "slot": 2, "type": "connect", "brief": {"headline": "Fedwire moved an average of $4.6 trillion a day in 2025, about $5.3 million per transfer. It moves money between banks that hold accounts at the Fed.", "kicker": "Connect day 1 and day 4: settlement is where value piles up.", "fullText": "On day 1 you saw that a payment is only a message until it settles, and that settlement happens between banks' accounts at the Fed. On day 4 you saw how much flows there: Fedwire moved an average of $4.6 trillion a day in 2025, at about $5.3 million per transfer.\n\nACH carries the count, 35.2 billion payments in 2025. Fedwire carries the value. When big sums must be final the same day, they move between Fed accounts.", "sources": [{"url": "https://www.moderntreasury.com/journal/difference-between-settlement-and-clearing", "label": "Modern Treasury, clearing vs settlement"}, {"url": "https://www.frbservices.org/financial-services/wires", "label": "Fedwire Funds Service"}, {"url": "https://frbservices.org/resources/financial-services/wires/volume-value-stats/annual-stats.html", "label": "Fedwire annual statistics"}, {"url": "https://www.nacha.org/news/same-day-ach-and-business-business-payments-propel-ach-network-volume-growth-2025", "label": "Nacha, ACH volume 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about Fedwire. Tap it.", "statements": ["It moves money between banks' Fed accounts.", "Its average transfer was about $5.3 million in 2025.", "Most of its transfers are small app payments."], "fakeIndex": 2, "explanation": "An average of $5.3 million is not app money. Fedwire is built for large transfers between banks."}, "numbers": {"kind": "numberSense", "prompt": "About how many trillion dollars did Fedwire move on an average day in 2025?", "min": 0, "max": 12, "value": 4.6, "unit": "T", "explanation": "About $4.6 trillion a day. Value piles up where settlement between banks happens."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're on a bank's treasury team. A client must pay $40 million today to close a deal.", "prompt": "Which rail do you suggest?", "options": ["Fedwire, so it settles between Fed accounts", "A payments app, since it looks instant", "Thousands of card payments"], "correctIndex": 0, "consequences": ["Large, final, same-day transfers are what Fedwire carries.", "An app balance is not settled money at another bank.", "Cards carry small payments, averaging about $52."], "explanation": "Big sums that must be final go between banks at the Fed. That is the job Fedwire does."}, "proReasoning": "Match the rail to the size and urgency. Large, final payments go by wire.", "commonMistake": "Choosing a rail by how fast it looks rather than when it settles.", "mentalModel": "Big and final means wire."}, "invest": {"call": {"kind": "theCall", "situation": "You're sizing the US payments market by value moved.", "prompt": "Which rail would be the worst to leave out?", "options": ["Checks written at stores", "Fedwire, at trillions a day", "Cards, at about $52 each"], "correctIndex": 1, "consequences": ["Store checks are a small slice of value.", "$4.6 trillion a day dwarfs card value.", "Cards lead on count, not value."], "explanation": "By value, Fedwire dominates. By count, ACH and cards lead. Pick the measure first."}, "proReasoning": "Investors decide whether they are measuring count or value. The leader changes with the measure.", "commonMistake": "Mixing count and value in one ranking.", "mentalModel": "Choose the measure, then the leader."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup helps small businesses pay their suppliers.", "prompt": "Does Fedwire's $5.3 million average describe your users?", "options": ["Yes, small firms send millions daily", "Yes, averages fit every user", "No, it reflects large institutions"], "correctIndex": 2, "consequences": ["Few small firms move millions a day.", "An average hides a wide spread of users.", "Small businesses rarely send transfers of that size."], "explanation": "The Fedwire average reflects big players. Size your product on your own users, not the rail average."}, "proReasoning": "Founders check whether a rail average matches their customer. Averages describe the rail, not your segment.", "commonMistake": "Assuming a rail's average describes your customers.", "mentalModel": "Averages describe rails, not users."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what a domestic wire transfer actually is.", "prompt": "What's the best answer?", "options": ["Money moved between banks at the Fed", "A message that never moves money", "A card payment that skips the store"], "correctIndex": 0, "consequences": ["Fedwire settles between banks' Fed accounts, often for big sums.", "A wire settles; it is not just a message.", "Cards and wires are different rails."], "explanation": "Domestic wires often run on Fedwire. Money moves between banks' accounts at the Fed and is final."}, "proReasoning": "A wire is settlement, not just a message. That is why people use it when money must be final today.", "commonMistake": "Thinking a wire is just a faster bank transfer.", "mentalModel": "A wire is settled money."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$376cfc0c-3b13-5a74-ae31-f33d48ce6e9c$ml$::uuid, $ml$fintech$ml$, 4, 3, $ml${"id": "fintech-d4-c3", "title": "Same day, more often", "lessonTitle": "The numbers behind the plumbing", "slot": 3, "type": "decide", "brief": {"headline": "In 2025, ACH carried 35.2 billion payments worth $93 trillion. Same Day ACH carried 1.4 billion payments worth $3.9 trillion, and its value grew 21.4%.", "kicker": "Decide whether faster ACH is worth building on.", "fullText": "Nacha reported 35.2 billion ACH payments in 2025, up nearly 5%, worth $93 trillion, up almost 8%. Same Day ACH carried 1.4 billion payments worth $3.9 trillion, and its value grew 21.4%. Business-to-business payments reached about 8.1 billion. December 2025 set a monthly record of 3.22 billion payments.\n\nYou run a startup that pays contractors for small firms. Clients ask whether money can arrive the same day.", "sources": [{"url": "https://www.nacha.org/news/same-day-ach-and-business-business-payments-propel-ach-network-volume-growth-2025", "label": "Nacha, ACH volume 2025"}, {"url": "https://frbservices.org/resources/financial-services/wires/volume-value-stats/annual-stats.html", "label": "Fedwire annual statistics"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each fact typical of ACH or of Fedwire?", "buckets": ["ACH", "Fedwire"], "items": [{"text": "35.2 billion payments in 2025", "bucket": 0}, {"text": "About $2,600 per payment", "bucket": 0}, {"text": "About 8.1 billion business payments", "bucket": 0}, {"text": "About $4.6 trillion a day", "bucket": 1}, {"text": "About $5.3 million per transfer", "bucket": 1}], "explanation": "ACH carries the count. Fedwire carries the value."}, "numbers": {"kind": "numberSense", "prompt": "Same Day ACH moved $3.9 trillion over 1.4 billion payments. About how many thousand dollars each?", "min": 0, "max": 10, "value": 2.8, "unit": "K", "explanation": "About $2,800, close to the $2,600 ACH average. Same day speed, similar sizes."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer at a payments company asks which part of ACH grew fastest by value in 2025.", "prompt": "What's your answer?", "options": ["Paper checks sent by mail", "Same Day ACH, up 21.4%", "ACH as a whole, up almost 8%"], "correctIndex": 1, "consequences": ["Checks are not part of the ACH figures.", "That is the fastest growth Nacha reported.", "True, but slower than Same Day ACH."], "explanation": "Same Day ACH value grew 21.4%, almost three times the network overall."}, "proReasoning": "Quote the growth rate that tells the trend. Same Day ACH growing much faster than ACH shows where demand is moving.", "commonMistake": "Quoting only the headline total.", "mentalModel": "The fastest-growing part tells the trend."}, "invest": {"call": {"kind": "theCall", "situation": "Same Day ACH value grew 21.4% in 2025, while ACH overall grew almost 8%.", "prompt": "What does that suggest?", "options": ["ACH is shrinking overall", "Speed makes no difference to users", "Faster rails are taking share"], "correctIndex": 2, "consequences": ["ACH value grew almost 8%.", "Users moved money to the faster option.", "Value is shifting toward faster settlement."], "explanation": "When the fast option grows far faster than the whole, users are paying for speed."}, "proReasoning": "Investors compare growth inside a rail. A fast segment outgrowing the whole signals where products will follow.", "commonMistake": "Reading growth totals without the mix.", "mentalModel": "Growth by segment shows the shift."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the contractor payments startup. Clients ask for pay that arrives the same day.", "prompt": "What do the numbers say?", "options": ["Same day demand is real and growing", "Nobody uses Same Day ACH yet", "Only Fedwire can pay the same day"], "correctIndex": 0, "consequences": ["1.4 billion payments and 21.4% value growth back it up.", "It carried 1.4 billion payments in 2025.", "Same Day ACH does it at ACH-sized amounts."], "explanation": "Same Day ACH is large and growing fast. Building on it meets a demand the data shows."}, "proReasoning": "Founders size a feature with rail data. A segment of 1.4 billion payments growing fast is a real market.", "commonMistake": "Guessing demand without checking the rail numbers.", "mentalModel": "Let the rail data size the feature."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend guesses that ACH handles a few million payments a year.", "prompt": "How far off is that?", "options": ["Too high: it was a few thousand", "Very: it was 35.2 billion in 2025", "Close: it was about 5 million"], "correctIndex": 1, "consequences": ["ACH set a record of 3.22 billion in one month.", "Thousands of times more, worth $93 trillion.", "Off by a factor of thousands."], "explanation": "ACH carried 35.2 billion payments in 2025. Most people use it without knowing."}, "proReasoning": "Pin one real number to a system people use without seeing. It makes the plumbing visible.", "commonMistake": "Underestimating rails because they are invisible.", "mentalModel": "Invisible rails carry billions."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$3d0acc71-8717-5a58-9523-5c13a7213a64$ml$::uuid, $ml$fintech$ml$, 5, 1, $ml${"id": "fintech-d5-c1", "title": "First Republic's long run", "lessonTitle": "Why a bank can fail in a day", "slot": 1, "type": "apply", "brief": {"headline": "First Republic lost more than $100 billion of deposits in the first quarter of 2023. Regulators closed it on May 1 and sold it to JPMorgan Chase.", "kicker": "Apply day 5: a run can outlast a rescue.", "fullText": "By the end of 2022, uninsured deposits made up upwards of two thirds of First Republic's deposits, an FDIC review found. After Silicon Valley Bank and Signature failed in March 2023, clients pulled more than $100 billion. Eleven large banks, including JPMorgan Chase, Citigroup, Bank of America and Wells Fargo, put in $30 billion to steady it. Deposits still fell more than 40% in the quarter, to $104.5 billion.\n\nThe bank disclosed the losses on April 24, and its stock plunged. Regulators closed it on May 1, 2023, and JPMorgan Chase took all its deposits and most of its assets. The FDIC estimated the cost to the Deposit Insurance Fund at about $13 billion.", "sources": [{"url": "https://www.sfexaminer.com/news/business/fdic-reports-pinpoints-cause-of-first-republic-bank-collapse/article_1144adca-4e80-11ee-87db-1fa0065a9eb6.html", "label": "San Francisco Examiner, FDIC report on First Republic's collapse, Sep 2023"}, {"url": "https://www.bankrate.com/banking/first-republic-bank-crisis", "label": "Bankrate, The First Republic Bank crisis"}, {"url": "https://philstar.com/business/2023/04/25/2261517/first-republic-bank-shares-dive-40-drop-deposits", "label": "AFP via Philstar, First Republic deposits drop 40%, Apr 2023"}]}, "evidence": {"kind": "buildChain", "prompt": "Put First Republic's fall in order.", "steps": ["SVB and Signature fail in March 2023", "First Republic's uninsured clients pull money", "Eleven big banks deposit $30 billion", "Deposit losses are disclosed on April 24", "Regulators close it and sell it to JPMorgan"], "explanation": "The rescue slowed the run but did not end it. Once trust was gone, the deposits kept leaving."}, "numbers": {"kind": "numberSense", "prompt": "First Republic's deposits fell in one quarter by more than what share?", "min": 0, "max": 100, "value": 40, "unit": "%", "explanation": "More than 40%, to $104.5 billion, even with $30 billion from other banks."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a bank risk team. They ask what First Republic teaches.", "prompt": "What's your best answer?", "options": ["Uninsured money can leave even after a rescue", "A $30 billion rescue always stops a bank run", "It failed only because of one bad loan"], "correctIndex": 0, "consequences": ["Over $100 billion left despite the help.", "Deposits kept falling after the $30 billion.", "The FDIC pointed to uninsured funding and rate risk."], "explanation": "With two thirds of deposits uninsured, confidence decided its fate more than any rescue."}, "proReasoning": "Risk teams start with funding: how much could leave, and how fast. First Republic answered both badly.", "commonMistake": "Believing a big rescue ends a run by itself.", "mentalModel": "Trust, not rescues, holds deposits."}, "invest": {"call": {"kind": "theCall", "situation": "A regional bank reports that two thirds of its deposits are uninsured.", "prompt": "How do you read that?", "options": ["It has no bearing on the bank or its stock", "Its funding could leave fast under stress", "Its deposits are extra safe and loyal"], "correctIndex": 1, "consequences": ["Funding risk can end a bank, and its stock.", "That was First Republic's share when it began to bleed.", "Uninsured depositors have the most reason to run."], "explanation": "Uninsured depositors move first in a panic. A high share means funding that can vanish quickly."}, "proReasoning": "Investors check the uninsured share before anything else in a bank scare. High shares mean fast exits.", "commonMistake": "Treating big deposits as a sign of strength.", "mentalModel": "Uninsured money runs first."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a startup in 2023. Your CFO says the $30 billion rescue makes your bank safe.", "prompt": "What do you check?", "options": ["Whether the rescue made the news", "Nothing, since big banks stepped in", "How much of your cash is above $250,000"], "correctIndex": 2, "consequences": ["Coverage, not press, decides what is safe.", "The bank still failed on May 1, 2023.", "Insurance, not headlines, protects your payroll."], "explanation": "Only insured deposits are guaranteed. Check how much of your cash sits above the limit."}, "proReasoning": "Founders protect payroll with insurance limits, not with headlines. A rescue can fail.", "commonMistake": "Relying on a rescue to keep uninsured cash safe.", "mentalModel": "Insurance beats headlines."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a bank could fail after rivals put in $30 billion.", "prompt": "What's the best answer?", "options": ["Over $100 billion left, far more than the help", "The rival banks took their money back early", "The bank spent the $30 billion on branches"], "correctIndex": 0, "consequences": ["The outflow was more than three times the rescue.", "The $30 billion was there; the outflow was far larger.", "The money was there to meet withdrawals."], "explanation": "The rescue was smaller than the run. When most deposits are uninsured, the money can keep leaving."}, "proReasoning": "Compare the size of the help with the size of the run. When the run is bigger, help only buys time.", "commonMistake": "Assuming a big number always solves the problem.", "mentalModel": "Compare the help with the hole."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$8ab0aae0-ac74-561f-a0f2-fe37d45ac70f$ml$::uuid, $ml$fintech$ml$, 5, 2, $ml${"id": "fintech-d5-c2", "title": "The rate gap has a flip side", "lessonTitle": "Why a bank can fail in a day", "slot": 2, "type": "connect", "brief": {"headline": "SVB's deposits grew from $63 billion in 2019 to $175 billion in 2022. When rates rose, the market value of its bonds fell by about $17 billion.", "kicker": "Connect day 2 and day 5: earning the gap carries rate risk.", "fullText": "On day 2 you saw how a bank earns: it takes deposits and lends or invests them at a higher rate. On day 5 you saw what can go wrong. SVB's deposits nearly tripled in three years, and about 94% sat above the insurance limit. Like any bank, it put them to work in loans and bonds.\n\nWhen interest rates rose, its bonds lost about $17 billion of market value. Depositors noticed and ran: $42 billion left on March 9, 2023. The same balance sheet that earns the gap can lose value when rates move.", "sources": [{"url": "https://economics.yale.edu/sites/default/files/2024-02/metrick-2024-the-failure-of-silicon-valley-bank-and-the-panic-of-2023.pdf", "label": "Metrick, The Failure of SVB (Yale)"}, {"url": "https://www.cnbc.com/2023/03/28/svb-customers-tried-to-pull-nearly-all-deposits-in-two-days-barr-says.html", "label": "CNBC, Barr testimony on SVB"}, {"url": "https://www.fdic.gov/news/press-releases/2026/fdic-insured-institutions-reported-return-assets-124-percent-and-net", "label": "FDIC, Q4 2025 banking profile"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about SVB. Tap it.", "statements": ["Its deposits grew from $63 billion to $175 billion.", "Rising rates cut its bonds by about $17 billion.", "Its deposits were almost all insured."], "fakeIndex": 2, "explanation": "About 94% of its deposits were above the limit. That made the run fast and large."}, "numbers": {"kind": "numberSense", "prompt": "SVB's deposits went from $63 billion to $175 billion. About how many times larger?", "min": 0, "max": 8, "value": 2.8, "unit": "x", "explanation": "About 2.8 times in three years. Fast deposit growth went into assets that later lost value."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing on a bank's treasury team. They ask how rising rates can hurt a bank.", "prompt": "What's your best answer?", "options": ["Rates only affect borrowers, not banks", "Its bonds lose market value as rates rise", "Higher rates always raise bank profits"], "correctIndex": 1, "consequences": ["Banks hold bonds whose prices move with rates.", "SVB's bonds lost about $17 billion that way.", "Margins can rise, but bond values fall."], "explanation": "Bonds bought at low rates are worth less when rates rise. That cost SVB about $17 billion."}, "proReasoning": "Treasury candidates name both sides: rates can widen the margin and cut bond values. SVB shows the second.", "commonMistake": "Saying higher rates are always good for banks.", "mentalModel": "Rates cut both ways for banks."}, "invest": {"call": {"kind": "theCall", "situation": "A bank bought long-term bonds when rates were low to earn a wider gap.", "prompt": "What do you check now that rates are higher?", "options": ["How many branches it has opened", "Whether its logo was updated", "How much those bonds have lost"], "correctIndex": 2, "consequences": ["Branch count doesn't show rate risk.", "Branding says nothing about the balance sheet.", "Losses on bonds can erode capital if they must be sold."], "explanation": "The gap earned on low-rate bonds comes with risk. Check the losses before trusting the margin."}, "proReasoning": "Investors look for unrealized bond losses when rates rise. SVB showed how they can surface in a run.", "commonMistake": "Judging a bank only by its margin.", "mentalModel": "Behind every gap sits a risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup's bank nearly tripled its deposits in three years and holds lots of bonds.", "prompt": "What would you ask before keeping all your cash there?", "options": ["How much its bonds lost as rates rose", "How fast its app sends payments", "Whether it sponsors startup events"], "correctIndex": 0, "consequences": ["Bond losses were what spooked SVB's depositors.", "App speed won't matter if the bank fails.", "Sponsorships say nothing about solvency."], "explanation": "Fast growth put into bonds at low rates was SVB's weak point. Ask about it directly."}, "proReasoning": "Founders ask hard questions of the bank holding their cash. Growth plus rate risk is a pattern worth spotting.", "commonMistake": "Picking a bank for its startup perks.", "mentalModel": "Ask what your bank's assets are worth."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a bank can lose money on safe government bonds.", "prompt": "What's the best answer?", "options": ["The bonds were stolen from the bank", "Their market value falls when rates rise", "The government refuses to repay them"], "correctIndex": 1, "consequences": ["Nothing was stolen; rates moved.", "Selling before maturity locks in that loss.", "The bonds would be repaid; their price fell meanwhile."], "explanation": "A bond paying low interest is worth less when new bonds pay more. Sell it early, and you take the loss."}, "proReasoning": "Safe from default isn't safe from price moves. A bank forced to sell early can lose money on solid bonds.", "commonMistake": "Thinking safe bonds never lose value.", "mentalModel": "Safe from default is not safe from rates."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$f24204c5-3759-5649-8f40-d151ed5aa9c5$ml$::uuid, $ml$fintech$ml$, 5, 3, $ml${"id": "fintech-d5-c3", "title": "Make your bank harder to run on", "lessonTitle": "Why a bank can fail in a day", "slot": 3, "type": "decide", "brief": {"headline": "You run a bank where most deposits sit above the $250,000 insurance limit. Since 1933, no one has lost a penny of insured deposits.", "kicker": "Decide how to make your bank harder to run on.", "fullText": "Banks lend and invest most of what is deposited, so no bank can repay everyone at once. FDIC insurance covers $250,000 per depositor, per bank, for each ownership category. Insured savers have no reason to rush the doors.\n\nCapital, the shareholders' money, absorbs losses before depositors do. At SVB, about 94% of deposits were uninsured, and many came from startups with large balances. Your bank looks more like SVB than you would like.", "sources": [{"url": "https://www.fdic.gov/resources/deposit-insurance/understanding-deposit-insurance", "label": "FDIC, understanding deposit insurance"}, {"url": "https://www.federalreserve.gov/monetarypolicy/reservereq.htm", "label": "Federal Reserve, reserve requirements"}, {"url": "https://economics.yale.edu/sites/default/files/2024-02/metrick-2024-the-failure-of-silicon-valley-bank-and-the-panic-of-2023.pdf", "label": "Metrick, The Failure of SVB (Yale)"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each make a run more or less likely?", "buckets": ["More likely", "Less likely"], "items": [{"text": "Most deposits above $250,000", "bucket": 0}, {"text": "Large losses on bonds", "bucket": 0}, {"text": "Many depositors from one industry", "bucket": 0}, {"text": "Deposits mostly insured", "bucket": 1}, {"text": "A thick capital cushion", "bucket": 1}], "explanation": "Uninsured, concentrated deposits and losses invite runs. Insurance and capital make trust less blind."}, "numbers": {"kind": "numberSense", "prompt": "You hold $400,000 in one ownership category at one bank. How many thousand dollars are insured?", "min": 0, "max": 600, "value": 250, "unit": "K", "explanation": "$250,000. The other $150,000 is uninsured at that bank."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a new risk analyst. The bank's uninsured share rose from 50% to 80% in a year.", "prompt": "What do you do?", "options": ["Celebrate the fast growth in deposits", "Wait for the next annual risk review", "Flag it to the risk committee as run risk"], "correctIndex": 2, "consequences": ["Growth in uninsured money is growth in run risk.", "SVB lost $42 billion in a single day.", "A rising uninsured share was a warning sign at SVB."], "explanation": "Uninsured deposits can leave in hours. A sharp rise deserves attention now, not next year."}, "proReasoning": "Risk analysts escalate trends early. Uninsured share and rate risk were the two that sank SVB.", "commonMistake": "Treating deposit growth as good news by default.", "mentalModel": "Escalate the trend, not the crisis."}, "invest": {"call": {"kind": "theCall", "situation": "Two banks earn the same return. One has 90% insured deposits; the other 90% uninsured.", "prompt": "Which has steadier funding?", "options": ["The mostly insured one", "The mostly uninsured one", "They are the same, since returns match"], "correctIndex": 0, "consequences": ["Insured savers have no reason to run.", "Uninsured money can leave in hours.", "Same return, very different funding risk."], "explanation": "Insured deposits stay put in a scare. Uninsured ones leave first."}, "proReasoning": "Investors adjust a bank's returns for funding risk. Equal returns on shakier funding are worth less.", "commonMistake": "Comparing banks on return alone.", "mentalModel": "Same return, different risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the bank. Startups with big balances supply most of your deposits.", "prompt": "What do you do first?", "options": ["Lend more so the bank grows faster", "Widen your depositor base and add capital", "Offer startups even higher deposit rates"], "correctIndex": 1, "consequences": ["Growth without a buffer adds risk.", "More small, insured depositors and more capital make runs less likely.", "That pulls in more of the money that runs first."], "explanation": "Concentrated, uninsured deposits caused SVB's run. Diversify and build the cushion."}, "proReasoning": "Bankers spread their depositors and hold enough capital to absorb losses. Both make trust less blind.", "commonMistake": "Chasing more of the same depositors.", "mentalModel": "Spread the deposits, thicken the cushion."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why insured savers didn't rush to pull money in 2023.", "prompt": "What's the best answer?", "options": ["They had not heard the news about SVB", "Banks blocked small withdrawals that week", "Their money was covered up to $250,000"], "correctIndex": 2, "consequences": ["The news was everywhere; insurance kept them calm.", "Withdrawals stayed open; there was little reason to rush.", "No one has lost insured deposits since 1933."], "explanation": "Insurance takes away the reason to run. That is why it was created."}, "proReasoning": "Explain insurance as a calm-down tool. People who know they are covered do not stampede.", "commonMistake": "Thinking panic hits all depositors equally.", "mentalModel": "Insurance removes the reason to run."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$9f776216-8a9b-5aae-af86-80a58e4033dd$ml$::uuid, $ml$fintech$ml$, 6, 1, $ml${"id": "fintech-d6-c1", "title": "$2.2 trillion still exposed", "lessonTitle": "The bank that closed mid-trade", "slot": 1, "type": "apply", "brief": {"headline": "In April 2022, about $2.2 trillion of currency trades a day still settled without payment versus payment protection. That was almost a third of deliverable FX turnover, the BIS found.", "kicker": "Apply day 6: Herstatt risk is still here.", "fullText": "A December 2022 BIS study used its 2022 Triennial Survey to measure how much foreign exchange still settles with one side exposed. In April 2022, $2.2 trillion a day, about 31% of deliverable turnover, settled on banks' own books without loss protection or through other non-PvP arrangements. That was up from an estimated $1.9 trillion in 2019. The share was unchanged, but trading had grown.\n\nCLS, which settles both sides together in 18 currencies, handled $2.5 trillion of the $3.5 trillion settled with risk mitigation. Trades between dealers tended to be protected; trades with customers less so. In some smaller trading locations, more than 75% went unprotected.", "sources": [{"url": "https://bis.org/publ/qtrpdf/r_qt2212i.htm", "label": "BIS Quarterly Review, FX settlement risk: an unsettled issue, Dec 2022"}, {"url": "https://www.bis.org/publ/qtrpdf/r_qt0212f.pdf", "label": "BIS Quarterly Review, CLS and FX settlement risk, Dec 2002"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What makes $2.2 trillion a day of currency trades exposed?", "options": ["The currencies could lose value", "One side can be paid before the other", "The trades break currency laws"], "correctIndex": 1, "explanation": "Without payment versus payment, one leg can settle while the other is still a promise."}, "numbers": {"kind": "numberSense", "prompt": "About what share of deliverable FX turnover settled without PvP protection in April 2022?", "min": 0, "max": 100, "value": 31, "unit": "%", "explanation": "About 31%, or $2.2 trillion a day. Almost half a century after Herstatt, the gap remains."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for an FX operations role. They ask why settlement risk still matters.", "prompt": "What's your best answer?", "options": ["It only matters if a German bank closes", "About $2.2 trillion a day settles unprotected", "CLS ended the problem for good back in 2002"], "correctIndex": 1, "consequences": ["Any counterparty failing mid-settlement causes it.", "A current number shows the risk is live, not history.", "CLS helped, but a third still settles unprotected."], "explanation": "The BIS found almost a third of deliverable FX still settles without PvP. The risk is current."}, "proReasoning": "Bring a current number to an old risk. The BIS figure shows Herstatt risk never went away.", "commonMistake": "Treating Herstatt risk as solved history.", "mentalModel": "Old risks, current numbers."}, "invest": {"call": {"kind": "theCall", "situation": "A bank's FX business grows fast with clients in emerging markets.", "prompt": "What do you ask?", "options": ["How many currencies it quotes on screen", "Whether its traders work late hours", "How much settles without PvP protection"], "correctIndex": 2, "consequences": ["Quote count says nothing about settlement.", "Hours worked do not measure risk.", "Customer and emerging market trades are less often protected."], "explanation": "The BIS found emerging market and customer trades more often unprotected. Growth there can add hidden exposure."}, "proReasoning": "Investors ask how a firm settles, not only how much it trades. Unprotected settlement is hidden risk.", "commonMistake": "Reading FX growth as pure upside.", "mentalModel": "Ask how the trades settle."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup wants to help firms settle currency trades more safely.", "prompt": "Which users feel the gap most?", "options": ["Customers, whose trades are less protected", "Large dealers trading with each other", "Nobody, since CLS covers everything"], "correctIndex": 0, "consequences": ["The BIS found customer trades less often risk-mitigated.", "Dealer trades tended to be protected already.", "CLS covers 18 currencies, not all trades."], "explanation": "The unprotected share sits with customers and smaller markets. That is where a product can help."}, "proReasoning": "Founders look for who is left out of the existing fix. Here, that is customers and smaller currencies.", "commonMistake": "Assuming an existing solution covers the whole market.", "mentalModel": "Find who the fix leaves out."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thought the Herstatt problem was solved in 2002.", "prompt": "What's the best answer?", "options": ["It was never a real problem", "CLS helped, but a third still settles exposed", "Yes, no currency trade can fail that way now"], "correctIndex": 1, "consequences": ["Banks lost real money when Herstatt closed.", "About $2.2 trillion a day was still exposed in 2022.", "Non-PvP settlement still carries the risk."], "explanation": "CLS removes the risk for trades it settles. Many trades still settle one side at a time."}, "proReasoning": "A fix only protects those who use it. Ask how much of the market is still outside it.", "commonMistake": "Assuming a known fix reached everyone.", "mentalModel": "A fix covers only its users."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$b50dd1ea-1cc6-5db7-9547-17cfb99241c7$ml$::uuid, $ml$fintech$ml$, 6, 2, $ml${"id": "fintech-d6-c2", "title": "Settled here, a promise there", "lessonTitle": "The bank that closed mid-trade", "slot": 2, "type": "connect", "brief": {"headline": "In 1974, banks paid Herstatt in marks, and that side settled. The dollars owed back were still a promise when regulators closed the bank at 3:30 pm.", "kicker": "Connect day 1 and day 6: one side settled, the other a message.", "fullText": "On day 1 you learned that a payment is only a message until it settles. On day 6 you saw what that means across time zones. On June 26, 1974, some banks had irrevocably paid Bankhaus Herstatt in Deutsche marks. The dollars due in return were to come once US markets opened. German authorities closed Herstatt at 15:30, and the dollars never arrived.\n\nOne leg was final; the other was still a promise. In September 2002, CLS Bank began settling both legs together, called payment versus payment.", "sources": [{"url": "https://www.bis.org/publ/qtrpdf/r_qt0212f.pdf", "label": "BIS Quarterly Review, CLS and FX settlement risk, Dec 2002"}, {"url": "https://www.moderntreasury.com/journal/difference-between-settlement-and-clearing", "label": "Modern Treasury, clearing vs settlement"}]}, "evidence": {"kind": "sortSignal", "prompt": "Settled and final, or still only a promise?", "buckets": ["Settled and final", "Still a promise"], "items": [{"text": "Marks paid to Herstatt in Germany", "bucket": 0}, {"text": "Both legs settled together through CLS", "bucket": 0}, {"text": "Money final at the receiving bank", "bucket": 0}, {"text": "Dollars due later in New York", "bucket": 1}, {"text": "An instruction sent but not settled", "bucket": 1}], "explanation": "Settlement makes money final. Anything still to come is only a promise, and promises can fail."}, "numbers": {"kind": "numberSense", "prompt": "CLS began settling both legs together in 2002. How many years after Herstatt?", "min": 0, "max": 80, "value": 28, "unit": "years", "explanation": "28 years. The gap that sank Herstatt's counterparties took decades to close for major currencies."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In a payments interview, you're asked to explain Herstatt in one line.", "prompt": "Which line works?", "options": ["The bank wired money to the wrong country", "Germany banned currency trading in 1974", "One leg settled; the other was still a promise"], "correctIndex": 2, "consequences": ["Nothing went to the wrong place; the return leg never came.", "Trading continued; one bank closed mid-trade.", "Clear, precise and tied to settlement."], "explanation": "Paid one side, never received the other. That one line shows you understand settlement risk."}, "proReasoning": "Compress a classic case into one line. It proves you know why settlement timing matters.", "commonMistake": "Telling the history without naming the risk.", "mentalModel": "Paid one side, never got the other."}, "invest": {"call": {"kind": "theCall", "situation": "A payments firm pays out to customers before the money from the other side has settled.", "prompt": "What are you looking at?", "options": ["Settlement risk, like Herstatt", "A firm with no risk at all", "A simple fee on each payment"], "correctIndex": 0, "consequences": ["If the incoming leg fails, the firm absorbs the loss.", "Paying before receiving always carries risk.", "Fees aside, the timing gap is the issue."], "explanation": "Any firm that pays before it receives carries the risk Herstatt made famous."}, "proReasoning": "Investors ask whether a firm pays before it gets paid. That gap is where losses hide.", "commonMistake": "Ignoring timing because the payments usually work.", "mentalModel": "Pay before you receive, and you carry risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your cross-border app pays recipients instantly, before the sender's funds settle.", "prompt": "What risk do you carry?", "options": ["None, since payouts feel instant", "Paying out and never receiving the funds", "Recipients complaining it's too fast"], "correctIndex": 1, "consequences": ["Feeling instant isn't the same as being settled.", "That is Herstatt risk at startup scale.", "Speed delights users; the risk is yours."], "explanation": "If you pay before the sender settles, a failed incoming leg becomes your loss."}, "proReasoning": "Founders who front money size the exposure and set limits. Speed for users is risk for you.", "commonMistake": "Treating a promised incoming payment as settled.", "mentalModel": "Fronting money is lending."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how banks lost money if they had already paid Herstatt.", "prompt": "What's the best answer?", "options": ["They paid with money they did not own", "Herstatt returned their marks too late", "Their payment was final; the return was not"], "correctIndex": 2, "consequences": ["They paid with their own marks, irrevocably.", "The marks were gone; the dollars were the issue.", "Final money left; promised dollars never came."], "explanation": "Paying is final once settled. Getting paid back was still a promise when the bank closed."}, "proReasoning": "Explain the risk as a two-step swap where only step one happened. Everyone gets it.", "commonMistake": "Thinking a trade happens all at once.", "mentalModel": "A swap can stop halfway."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$f37e6656-647e-569a-a632-2802c336c362$ml$::uuid, $ml$fintech$ml$, 6, 3, $ml${"id": "fintech-d6-c3", "title": "How much will your desk front?", "lessonTitle": "The bank that closed mid-trade", "slot": 3, "type": "decide", "brief": {"headline": "You run the FX desk at a mid-size bank. A client wants to trade a currency pair that you settle one leg at a time.", "kicker": "Decide how much timing risk your desk will carry.", "fullText": "When Herstatt closed in 1974, banks that had paid it marks never received their dollars. That danger is called Herstatt risk, or foreign exchange settlement risk. Since September 2002, CLS Bank has settled both legs of trades together, payment versus payment, in the currencies it covers.\n\nThis client's currency is outside that setup. Your desk would pay first and receive hours later. The gap between paying and getting paid is where losses hide.", "sources": [{"url": "https://www.bis.org/publ/qtrpdf/r_qt0212f.pdf", "label": "BIS Quarterly Review, CLS and FX settlement risk, Dec 2002"}, {"url": "https://bis.org/publ/qtrpdf/r_qt2212i.htm", "label": "BIS Quarterly Review, FX settlement risk: an unsettled issue, Dec 2022"}]}, "evidence": {"kind": "faceOff", "prompt": "Which setup removes Herstatt risk?", "left": {"name": "Payment versus payment", "note": "Both legs settle at the same moment"}, "right": {"name": "Pay first, collect later", "note": "One leg settles hours before the other"}, "correctIndex": 0, "explanation": "When both legs settle together, neither side can pay and be left waiting."}, "numbers": {"kind": "numberSense", "prompt": "CLS settles both legs together in how many currencies, per the BIS?", "min": 0, "max": 50, "value": 18, "unit": "currencies", "explanation": "18. Trades in other currencies need another way to limit the gap."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're an FX operations analyst. A trade would pay out at 9 am and receive at 4 pm.", "prompt": "What do you do?", "options": ["Flag the exposure and check it against limits", "Ignore it, since it settles the same day", "Delay the outgoing payment without telling anyone"], "correctIndex": 0, "consequences": ["Seven hours of exposure is the kind of gap Herstatt exposed.", "Herstatt closed mid-afternoon on a single day.", "Unilateral delays break the trade terms."], "explanation": "Same day is not same moment. The hours between paying and receiving carry real risk."}, "proReasoning": "Operations analysts measure exposure in hours and amounts. Same-day settlement can still hide a gap.", "commonMistake": "Assuming same-day settlement means no risk.", "mentalModel": "Same day is not same moment."}, "invest": {"call": {"kind": "theCall", "situation": "A bank says most of its FX trades settle through CLS.", "prompt": "Why does that reassure you?", "options": ["CLS trades are free of all fees", "Both legs settle together, so no gap", "CLS guarantees the bank is profitable"], "correctIndex": 1, "consequences": ["Fees are not the point; settlement risk is.", "Payment versus payment removes the Herstatt gap.", "CLS protects settlement, not profits."], "explanation": "Settling through CLS means the bank never pays one side without receiving the other."}, "proReasoning": "Investors read PvP use as lower settlement risk. They also ask what share of trades sits outside it.", "commonMistake": "Confusing settlement safety with profitability.", "mentalModel": "PvP closes the gap."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the desk. The client's currency isn't covered by payment versus payment.", "prompt": "What do you do?", "options": ["Pay first and trust the client fully", "Refuse trades in every currency", "Cap how much you pay before you receive"], "correctIndex": 2, "consequences": ["Herstatt's counterparties trusted too.", "That gives up good business to avoid a bounded risk.", "A limit keeps a failure survivable."], "explanation": "Where PvP is not available, limit how much you front. A capped gap is a manageable gap."}, "proReasoning": "Desk heads set limits where they cannot remove risk. The question is how much you can afford to lose.", "commonMistake": "Choosing between blind trust and refusing all business.", "mentalModel": "Cap what you cannot remove."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what payment versus payment means.", "prompt": "What's the best answer?", "options": ["Both sides of a trade settle at once", "Each side pays a fee to the other", "A trade settles only on payday"], "correctIndex": 0, "consequences": ["Neither side can pay and be left waiting.", "It is about timing, not fees.", "It is about simultaneity, not the calendar."], "explanation": "PvP means both legs settle together, so no one pays without getting paid."}, "proReasoning": "Picture a swap where both hands let go at the same moment. That is payment versus payment.", "commonMistake": "Thinking PvP is about price.", "mentalModel": "Both hands let go together."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$ce88566c-3612-56c5-882f-dc94eee24cfc$ml$::uuid, $ml$fintech$ml$, 7, 1, $ml${"id": "fintech-d7-c1", "title": "Brazil's always-on rail", "lessonTitle": "The rails money travels on", "slot": 1, "type": "apply", "brief": {"headline": "Brazil's central bank launched Pix in November 2020. In 2024 it carried about 64 billion payments, 80% more than credit and debit cards combined, a Matera study found.", "kicker": "Apply day 7: people follow the rail that wins on speed, cost and hours.", "fullText": "Pix is an instant payment platform created and run by the Central Bank of Brazil. Transfers between people work 24 hours a day, including weekends and holidays, and are free for individuals. Merchants pay about 0.33% per payment, by one estimate, against 1.13% for debit cards and 2.34% for credit cards.\n\nIn 2024, Pix carried about 64 billion transactions, up 53%, or over 6 billion a month. On December 20, 2024, it set a daily record of 252.1 million. By the end of 2024, 76.4% of Brazilians used Pix, more than used debit cards or cash.\n\nDay 7's rule at the scale of a country: the rail sets the speed, the cost and the hours.", "sources": [{"url": "https://www.paymentsjournal.com/brazils-pix-set-records-surpassing-credit-card-transactions-last-year/amp/", "label": "PaymentsJournal, Brazil's Pix set records, surpassing card transactions, Jan 2025"}, {"url": "https://gfmag.com/transaction-banking/pix-becomes-brazils-top-transaction-method/", "label": "Global Finance, Pix becomes Brazil's top transaction method, Jul 2025"}, {"url": "https://en.wikipedia.org/wiki/Pix_(payment_system)", "label": "Wikipedia, Pix (payment system)"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each feature true of Pix or of FedACH?", "buckets": ["Pix", "FedACH"], "items": [{"text": "Instant transfers on a Sunday", "bucket": 0}, {"text": "Free for transfers between people", "bucket": 0}, {"text": "Run by Brazil's central bank", "bucket": 0}, {"text": "Closed on weekends and holidays", "bucket": 1}, {"text": "Run by the US Federal Reserve", "bucket": 1}], "explanation": "Pix runs around the clock and is free between people. FedACH closes on weekends and holidays."}, "numbers": {"kind": "numberSense", "prompt": "On its record day, December 20, 2024, how many million Pix payments went through?", "min": 0, "max": 600, "value": 252.1, "unit": "M", "explanation": "252.1 million in one day. A free, always-on rail gets used for everything."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing on a US bank's payments team. They ask what Pix shows about rails.", "prompt": "What's your best answer?", "options": ["Only cards can ever win everyday payments", "Rails don't matter at all; only the apps do", "A free, always-on rail can beat cards on count"], "correctIndex": 2, "consequences": ["Pix overtook cards on count in 2024.", "Pix is a rail, and it changed how a country pays.", "Pix carried 80% more payments than cards combined."], "explanation": "Pix won on speed, cost and hours. Naming those three shows you understand why rails matter."}, "proReasoning": "Explain a rail by its speed, cost and hours. Pix wins on all three for everyday payments in Brazil.", "commonMistake": "Crediting an app for what the rail underneath made possible.", "mentalModel": "Speed, cost, hours: the rail decides."}, "invest": {"call": {"kind": "theCall", "situation": "Pix grew 53% in 2024, and merchants pay far less on it than on cards.", "prompt": "Who has the most to lose?", "options": ["Card businesses earning on Brazilian swipes", "Brazil's central bank, which runs Pix", "Nobody, since rails never compete"], "correctIndex": 0, "consequences": ["Each payment that moves to Pix is a swipe fee not earned.", "It runs the rail; card fees are not its income.", "Pix took count from cards; rails do compete."], "explanation": "When a cheaper rail grows fast, the fees on the older rail are the pool at risk."}, "proReasoning": "Investors ask whose revenue a new rail displaces. Pix grows at the expense of card fees.", "commonMistake": "Treating a public rail as irrelevant to private card businesses.", "mentalModel": "A cheaper rail eats the old toll."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're launching a checkout product for online shops in Brazil.", "prompt": "Which payment method do you support first?", "options": ["Bank wires sent during work hours", "Pix, which most Brazilians already use", "Credit cards only, like in the US"], "correctIndex": 1, "consequences": ["Pix already does the job any hour, for less.", "76.4% of Brazilians used Pix by the end of 2024.", "Cards lag Pix on count, and cost merchants more."], "explanation": "Build on the rail customers already use. In Brazil, that is Pix."}, "proReasoning": "Founders start with the rail their market already lives on. Copying the US card stack can miss the point abroad.", "commonMistake": "Assuming every country pays the way the US does.", "mentalModel": "Build on the rail people use."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend back from Brazil asks why everyone there paid with Pix instead of cards.", "prompt": "What's the best answer?", "options": ["Cards are banned in Brazilian shops", "Pix pays shoppers cash back on every sale", "It's instant, always on and free for people"], "correctIndex": 2, "consequences": ["Cards work there, but Pix is used more.", "Pix wins on speed and cost, not rewards.", "That combination beats cards for everyday payments."], "explanation": "Pix is instant, runs 24 hours a day and is free between people. That is hard for cards to match."}, "proReasoning": "Explain a payment habit by the rail behind it. Speed, cost and hours usually explain the choice.", "commonMistake": "Putting a habit down to culture when the rail explains it.", "mentalModel": "Habits follow the cheapest fast rail."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$60f782e9-09a8-56bf-85d9-8d3c00ba7cbe$ml$::uuid, $ml$fintech$ml$, 7, 2, $ml${"id": "fintech-d7-c2", "title": "The message is not the money", "lessonTitle": "The rails money travels on", "slot": 2, "type": "connect", "brief": {"headline": "Swift links over 12,500 institutions in more than 220 countries and territories. It carries payment instructions; the banks carry out the transfers.", "kicker": "Connect day 1 and day 7: Swift carries the message, not the money.", "fullText": "On day 1 you learned that a payment is only a message until it settles. On day 7 you met the world's biggest payment messaging network. Swift, a cooperative founded in 1973 and based in Belgium, runs secure messaging that banks use to send payment instructions. It says it does not move money; banks carry out the transfers.\n\nSo a Swift message is step one of day 1's chain. Clearing and settlement still have to happen between banks before the money is final.", "sources": [{"url": "https://swift.com/about-us/who-we-are", "label": "Swift, Who we are"}, {"url": "https://www.moderntreasury.com/journal/difference-between-settlement-and-clearing", "label": "Modern Treasury, clearing vs settlement"}]}, "evidence": {"kind": "faceOff", "prompt": "A bank in Paris sends a Swift message to a bank in New York. Has the money moved yet?", "left": {"name": "Not yet", "note": "The message is an instruction"}, "right": {"name": "Yes", "note": "Swift moved the funds"}, "correctIndex": 0, "explanation": "Swift carries the instruction. The banks still have to settle before the money is final."}, "numbers": {"kind": "numberSense", "prompt": "Swift links over how many thousand institutions?", "min": 0, "max": 30, "value": 12.5, "unit": "K", "explanation": "Over 12,500, in more than 220 countries and territories. All of them exchange messages, not money."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're in a bank's operations team. A client says the Swift went through, but the money hasn't arrived.", "prompt": "What do you explain?", "options": ["The message arrived; the banks still settle", "Swift has lost the money in transit", "The payment is final, so it must be there"], "correctIndex": 0, "consequences": ["Swift carries instructions, and settlement comes after.", "Swift never held the money to lose.", "A message is not settlement."], "explanation": "A Swift confirmation means the instruction arrived. The money moves when banks settle."}, "proReasoning": "Operations teams separate message status from settlement status. Clients calm down when you say which one is done.", "commonMistake": "Treating a delivered message as delivered money.", "mentalModel": "Message delivered is not money delivered."}, "invest": {"call": {"kind": "theCall", "situation": "A startup pitches itself as the Swift of a new market.", "prompt": "What should that tell you about its model?", "options": ["It will settle payments at the Fed", "It carries messages; others move money", "It will hold and lend customer money"], "correctIndex": 1, "consequences": ["Swift does not settle; banks do.", "A messaging network depends on banks to settle.", "Swift holds no customer money."], "explanation": "Swift is messaging. A business built like it earns from carrying instructions, not from holding money."}, "proReasoning": "Investors check which layer a firm sits on. A messaging layer and a settlement layer earn in different ways.", "commonMistake": "Assuming a payments network holds the money it routes.", "mentalModel": "Know which layer it sits on."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're building a cross-border payments app for small importers.", "prompt": "What does Swift give you?", "options": ["A finished way to move the money", "A license to hold customer funds", "Messages to banks; banks still settle"], "correctIndex": 2, "consequences": ["Swift sends instructions; the money moves elsewhere.", "Swift membership is not a license to hold money.", "You still need banks to carry out the transfers."], "explanation": "Swift is the messaging layer. Your product still needs banks that settle."}, "proReasoning": "Founders map each layer: who sends the message, who settles, who holds the funds. Swift covers only the first.", "commonMistake": "Planning as if messaging solves settlement.", "mentalModel": "Map message, settlement and custody."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks Swift is a giant bank holding everyone's money.", "prompt": "What's the best answer?", "options": ["It's a messaging network; banks move money", "It's the world's biggest savings bank", "It's a central bank owned by Belgium"], "correctIndex": 0, "consequences": ["Swift carries instructions for over 12,500 institutions.", "Swift takes no deposits.", "Swift is a cooperative, not a central bank."], "explanation": "Swift is a cooperative that carries payment messages. Banks do the transfers."}, "proReasoning": "Picture Swift as a secure postal service for banks. The letters say pay; the banks do the paying.", "commonMistake": "Thinking the network that carries payment messages holds the money.", "mentalModel": "Swift sends the letter; banks pay."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$44043cb0-1064-50b5-876f-9338008d636a$ml$::uuid, $ml$fintech$ml$, 7, 3, $ml${"id": "fintech-d7-c3", "title": "Saturday payouts", "lessonTitle": "The rails money travels on", "slot": 3, "type": "decide", "brief": {"headline": "You run a gig work app. Drivers want Saturday payouts, but the Fed's FedACH system is closed on weekends. RTP and FedNow settle instantly around the clock.", "kicker": "Decide which rail your payouts should run on.", "fullText": "The Fed's FedACH system is closed on weekends and holidays. The RTP network, launched in 2017 by large banks, and the Fed's FedNow service, launched on July 20, 2023, settle payments instantly, around the clock.\n\nIn payments, the rail you choose sets the speed, the cost and the hours. Your drivers finish shifts on Friday nights and Saturdays.", "sources": [{"url": "https://en.wikipedia.org/wiki/FedNow", "label": "FedNow"}, {"url": "https://paymentsdive.com/news/real-time-payments-network-transacion-limit-increase/734710", "label": "Payments Dive, RTP raises transaction limit to $10 million, Dec 2024"}, {"url": "https://swift.com/about-us/who-we-are", "label": "Swift, Who we are"}]}, "evidence": {"kind": "multipleChoice", "prompt": "A driver asks to be paid at 10 pm on a Saturday. Which rail can settle it then?", "options": ["FedACH", "A Swift message alone", "RTP or FedNow"], "correctIndex": 2, "explanation": "Instant rails run 24/7. FedACH is closed on weekends, and Swift only carries messages."}, "numbers": {"kind": "numberSense", "prompt": "RTP launched in 2017 and FedNow in 2023. How many years apart?", "min": 0, "max": 20, "value": 6, "unit": "years", "explanation": "Six years. The banks built an instant rail first; the Fed followed."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a product manager at the gig app. Engineering asks which rail should power Saturday payouts.", "prompt": "What do you choose?", "options": ["Swift, since it is global", "An instant rail like RTP or FedNow", "FedACH, since it is widely used"], "correctIndex": 1, "consequences": ["Swift sends messages; it does not settle.", "They settle on weekends, which is the whole point.", "FedACH is closed on weekends."], "explanation": "The feature needs settlement on a Saturday. Only the instant rails offer that."}, "proReasoning": "Product managers name the rail behind a feature. Weekend payouts need a rail that is open on weekends.", "commonMistake": "Picking the most familiar rail instead of the one that fits.", "mentalModel": "The feature picks the rail."}, "invest": {"call": {"kind": "theCall", "situation": "A gig app adds weekend payouts that run on FedNow.", "prompt": "What does that give it?", "options": ["Nothing a FedACH app lacks", "Lower fraud on every payment", "A feature batch rails cannot offer"], "correctIndex": 2, "consequences": ["FedACH apps cannot pay out on Sundays.", "Speed does not lower fraud; it can raise the stakes.", "Weekend settlement is only possible on instant rails."], "explanation": "Instant rails make new features possible. Weekend payouts are one of them."}, "proReasoning": "Investors look for features the rail makes possible and rivals on older rails cannot copy quickly.", "commonMistake": "Treating the payout rail as a back-office detail.", "mentalModel": "New rails, new features."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the gig app. Some drivers want pay right away; others don't mind waiting.", "prompt": "How do you design payouts?", "options": ["Instant on RTP or FedNow, standard on ACH", "Everything on FedACH to keep it simple", "Pay everyone by Swift transfer"], "correctIndex": 0, "consequences": ["Each driver gets the speed they value.", "Weekend drivers would wait until Monday.", "Swift carries messages and fits cross-border, not this."], "explanation": "Different users value speed differently. Offer both rails and let them choose."}, "proReasoning": "Founders let users pick their rail when speed matters to some and not others.", "commonMistake": "Forcing every user onto one rail.", "mentalModel": "Let users choose their speed."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why their paycheck never lands on a Sunday.", "prompt": "What's the likely reason?", "options": ["The law bans paying people on Sundays", "Their payroll runs on a rail closed on weekends", "Banks tend to lose track of money on Sundays"], "correctIndex": 1, "consequences": ["Instant rails pay on Sundays legally.", "FedACH is closed on weekends and holidays.", "Nothing is lost; the rail is just shut."], "explanation": "Payroll often runs on batch rails. Those rails keep business hours."}, "proReasoning": "When money waits for Monday, look at the rail. Some keep business hours; instant ones never close.", "commonMistake": "Blaming the bank when the rail sets the hours.", "mentalModel": "The rail keeps the hours."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$e6865005-2642-59c9-b256-849818eb0325$ml$::uuid, $ml$fintech$ml$, 8, 1, $ml${"id": "fintech-d8-c1", "title": "Ten basis points for five years", "lessonTitle": "Who collects the swipe fees", "slot": 1, "type": "apply", "brief": {"headline": "In November 2025, Visa and Mastercard agreed to cut US credit card swipe fees by 0.1 percentage point for five years. Merchants could also turn down premium rewards cards.", "kicker": "Apply day 8: a cut to the swipe toll is a cut to issuers.", "fullText": "The deal aims to settle a long-running merchant lawsuit. It splits credit cards into three groups: commercial, premium consumer and standard consumer. Merchants could choose which groups to accept. Rates on standard consumer cards would be capped at 1.25%, and the average effective credit interchange rate cut by 10 basis points for five years. Typical rates were 2% to 2.5%.\n\nJudge Margo Brodie in Brooklyn had rejected an earlier $30 billion version in June 2024, which would have cut fees by about 0.07 percentage points, calling the savings paltry. The Merchants Payments Coalition called the new cut minuscule. A judge granted preliminary approval in June 2026.\n\nThrough the day 8 lens: interchange is paid to the bank that issued the card, so a cut lands mainly on issuers.", "sources": [{"url": "https://www.rte.ie/news/business/2025/1110/1543170-visa-mastercard-reach-settlement-deal", "label": "RTÉ, Visa and Mastercard reach settlement deal, Nov 2025"}, {"url": "https://www.americascreditunions.org/node/27531", "label": "America's Credit Unions, Court grants preliminary approval to interchange settlement, Jun 2026"}, {"url": "https://www.everycrsreport.com/reports/R41913.html", "label": "Congressional Research Service, Regulation of debit interchange fees"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the 2025 deal. Tap it.", "statements": ["Merchants could choose which card groups to accept.", "Standard consumer card rates would be capped at 1.25%.", "The deal would abolish interchange fees."], "fakeIndex": 2, "explanation": "The deal trims interchange by 10 basis points for five years. The toll stays."}, "numbers": {"kind": "numberSense", "prompt": "By how many basis points would the average credit interchange rate fall, for five years?", "min": 0, "max": 50, "value": 10, "unit": "bp", "explanation": "10 basis points, or 0.1 percentage point, on typical rates of 2% to 2.5%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a card-issuing bank. They ask what the settlement means for the business.", "prompt": "What's your best answer?", "options": ["Slightly less interchange on credit swipes", "Higher fees collected from merchants", "Nothing, since networks keep all fees"], "correctIndex": 0, "consequences": ["Interchange goes to issuers, so a cut trims their income.", "The deal lowers fees; it does not raise them.", "Interchange is paid to the issuing bank."], "explanation": "Issuers collect interchange. A cut of 10 basis points comes out of their fee income."}, "proReasoning": "Say who pays interchange and who receives it. Then any fee news maps straight onto the issuer.", "commonMistake": "Assuming the networks keep the whole swipe fee.", "mentalModel": "Interchange flows to the issuer."}, "invest": {"call": {"kind": "theCall", "situation": "Under the deal, merchants could refuse premium rewards cards while still taking standard ones.", "prompt": "Which issuers face the most risk?", "options": ["Issuers of debit cards only", "Those whose cards are mostly premium", "Those with mostly standard cards"], "correctIndex": 1, "consequences": ["The deal covers credit cards.", "If shops refuse premium cards, those issuers lose swipes.", "Standard cards keep their place, with a rate cap."], "explanation": "A new right to refuse a category puts that category at risk first."}, "proReasoning": "Investors look for the segment a rule exposes. Here it is premium rewards cards that shops may now decline.", "commonMistake": "Treating all card issuers as equally affected.", "mentalModel": "Find the segment the rule exposes."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build checkout software for small merchants.", "prompt": "What feature does the deal invite?", "options": ["Help shoppers earn more rewards on their cards", "Ban cards from small shops entirely", "Help merchants pick which card groups to take"], "correctIndex": 2, "consequences": ["The deal is about merchant costs, not shopper rewards.", "The deal adds choice; it does not ban cards.", "Merchants gain choices and need tools to use them."], "explanation": "New acceptance and surcharging options need software. Merchants will want help using them."}, "proReasoning": "Founders watch for new merchant rights. Each new choice creates a need for tools to make it.", "commonMistake": "Ignoring a rule change that opens a product gap.", "mentalModel": "New rights need new tools."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend worries that stores might stop taking their premium rewards card.", "prompt": "Why could that happen?", "options": ["The deal lets shops refuse premium card groups", "The card was quietly cancelled by its bank", "Rewards cards are being made illegal"], "correctIndex": 0, "consequences": ["Merchants could accept or decline by group.", "The card still works; a shop may decline it.", "No such ban is in the deal."], "explanation": "The settlement lets merchants choose among commercial, premium and standard cards."}, "proReasoning": "Card acceptance is a contract between merchants and networks. Change the contract, and what shops take can change.", "commonMistake": "Assuming every store must take every card forever.", "mentalModel": "Acceptance is a contract."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$5c677510-a9f5-5a76-ac66-9bf3310a90f4$ml$::uuid, $ml$fintech$ml$, 8, 2, $ml${"id": "fintech-d8-c2", "title": "The swipe in the bank's income", "lessonTitle": "Who collects the swipe fees", "slot": 2, "type": "connect", "brief": {"headline": "US merchants paid $236.4 billion in card swipe fees in 2024, per CMSPI. Part of each fee is interchange, paid to the bank that issued the card.", "kicker": "Connect day 2 and day 8: swipe fees feed banks' fee income.", "fullText": "On day 2 you saw that banks earn in two ways: the rate gap, and fees such as card and account fees. On day 8 you followed one of those fees. CMSPI put US swipe fees at $236.4 billion in 2024, up from $222.3 billion in 2023, with Visa and Mastercard credit card fees making up $122.3 billion.\n\nInterchange, part of each swipe fee, goes to the card-issuing bank. It counts as fee income and does not depend on the rate gap.", "sources": [{"url": "https://nsga.org/news/swipe-fees-totaled-236-billion-in-2024/", "label": "NSGA on CMSPI, swipe fees totaled $236 billion in 2024, Sep 2025"}, {"url": "https://www.everycrsreport.com/reports/R41913.html", "label": "Congressional Research Service, Regulation of debit interchange fees"}, {"url": "https://www.fdic.gov/quarterly-banking-profile/statistics-glance-industry-trends-fourth-quarter-2025.pdf", "label": "FDIC, industry at a glance Q4 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each item interest income or fee income for a bank?", "buckets": ["Interest income", "Fee income"], "items": [{"text": "Interest on a mortgage", "bucket": 0}, {"text": "Interest on reserves at the Fed", "bucket": 0}, {"text": "Interchange on a debit swipe", "bucket": 1}, {"text": "Interchange on a credit swipe", "bucket": 1}, {"text": "Monthly account fees", "bucket": 1}], "explanation": "Interchange is fee income. It grows with spending, not with the rate gap."}, "numbers": {"kind": "numberSense", "prompt": "Visa and Mastercard credit fees made up how many billion of the $236.4 billion?", "min": 0, "max": 300, "value": 122.3, "unit": "B", "explanation": "$122.3 billion, more than half of the total."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing in a bank's card business. They ask where swipe revenue comes from.", "prompt": "What's your answer?", "options": ["Interest the Fed pays on card balances", "Interchange that merchants pay on swipes", "A payment from shoppers on each swipe"], "correctIndex": 1, "consequences": ["The Fed pays interest on reserves, not cards.", "Merchants pay it, and the issuing bank receives it.", "Shoppers do not pay a fee per swipe."], "explanation": "Merchants pay the swipe fee. Interchange is the part that goes to the issuer."}, "proReasoning": "Trace the swipe fee from merchant to issuer. It shows you know which side of the bank it feeds.", "commonMistake": "Thinking shoppers pay the swipe fee directly.", "mentalModel": "Merchants pay; issuers collect."}, "invest": {"call": {"kind": "theCall", "situation": "Swipe fees rose from $222.3 billion in 2023 to $236.4 billion in 2024.", "prompt": "Why do issuers like that trend?", "options": ["It raises their margins on mortgages", "It lowers what they pay savers", "Fee income grows with spending, not rates"], "correctIndex": 2, "consequences": ["Mortgages earn the rate gap, not swipe fees.", "Deposit costs are a separate line.", "Interchange rises as people swipe more."], "explanation": "Interchange is fee income that tracks spending. It adds a second engine beside the rate gap."}, "proReasoning": "Investors value fee income that does not depend on rates. A growing swipe pool is one source.", "commonMistake": "Lumping card fees in with the rate gap.", "mentalModel": "Fees track spending."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your fintech offers a debit card through a partner bank.", "prompt": "Where could its revenue come from?", "options": ["A share of the interchange on each swipe", "A fee charged to the Fed for each card", "Interest earned from the networks"], "correctIndex": 0, "consequences": ["The issuing bank earns interchange and can share it.", "The Fed does not pay per card.", "Networks charge fees; they do not pay interest."], "explanation": "Interchange goes to the issuing bank. A fintech can earn a share by contract."}, "proReasoning": "Founders behind card products read the interchange split in their bank contract first.", "commonMistake": "Planning card revenue without knowing who gets interchange.", "mentalModel": "Know your share of the swipe."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks who earns money when they tap their card at a café.", "prompt": "What's the best answer?", "options": ["Only the café, from your purchase", "The bank that issued the card, among others", "Nobody, since card payments are always free"], "correctIndex": 1, "consequences": ["The café gets the sale minus the fee.", "Interchange from the café goes to your card issuer.", "The café pays a swipe fee on every tap."], "explanation": "Each swipe pays a toll. The card-issuing bank collects the interchange part of it."}, "proReasoning": "Every swipe pays a toll you never see. Merchants pay it and banks collect part of it.", "commonMistake": "Thinking card payments cost nothing.", "mentalModel": "Every swipe pays a toll."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$51dea6c0-24a0-596a-a6d7-57f8ab1218b5$ml$::uuid, $ml$fintech$ml$, 8, 3, $ml${"id": "fintech-d8-c3", "title": "A cap on borrowed time", "lessonTitle": "Who collects the swipe fees", "slot": 3, "type": "decide", "brief": {"headline": "Since October 2011, big banks' debit interchange has been capped at 21 cents plus 0.05% of the sale. In August 2025 a court ruled the cap unlawful, but paused the ruling for the appeal.", "kicker": "Decide how to plan around a cap that could change.", "fullText": "The Fed's rule caps debit interchange at banks with $10 billion or more in assets at 21 cents plus 0.05% of the transaction, plus 1 cent for issuers that meet fraud-prevention standards. When the Fed proposed it in 2010, debit interchange averaged 44 cents.\n\nIn August 2025, a federal court in North Dakota ruled the Fed's rule unlawful but paused its decision while the Fed appeals, so the cap still applies. You run a coffee chain where most sales are small debit purchases.", "sources": [{"url": "https://www.everycrsreport.com/reports/R41913.html", "label": "Congressional Research Service, Regulation of debit interchange fees"}, {"url": "https://www.cooley.com/news/insight/2025/2025-08-15-district-court-vacates-regulation-iis-debit-card-interchange-fee-standard", "label": "Cooley, District court vacates Regulation II debit interchange fee standard, Aug 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow the fee on one debit sale.", "steps": ["A customer taps a debit card for $5", "The card's issuing bank approves the sale", "The store pays a swipe fee on the sale", "Interchange lands at the issuing bank"], "explanation": "The store pays, and the issuer collects interchange. For big issuers, the Fed caps it."}, "numbers": {"kind": "numberSense", "prompt": "Under the cap, interchange on a $100 debit sale is 21 cents plus 0.05%. How many cents, before the fraud cent?", "min": 0, "max": 100, "value": 26, "unit": "¢", "explanation": "21 cents plus 5 cents is 26 cents, or 27 with the fraud-prevention cent."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a payments analyst at a retailer. Your boss asks what the August 2025 ruling changed.", "prompt": "What's your answer?", "options": ["Debit fees doubled the next morning", "All debit interchange was abolished", "Nothing yet; the cap holds during appeal"], "correctIndex": 2, "consequences": ["The ruling was paused, so fees did not jump.", "The ruling was about the cap, not abolition.", "The court paused its ruling, so the cap still applies."], "explanation": "A paused ruling changes nothing until appeals end. Explaining that saves bad decisions."}, "proReasoning": "Analysts separate a ruling from its effect. A paused decision is a risk to plan for, not a change to act on.", "commonMistake": "Reacting to a headline about a ruling that has been paused.", "mentalModel": "A paused ruling is a risk, not a change."}, "invest": {"call": {"kind": "theCall", "situation": "If the cap were struck down for good, big banks could charge more per debit swipe.", "prompt": "Who would gain most?", "options": ["Big debit issuers over $10 billion", "Small banks that are already exempt", "Merchants who accept debit"], "correctIndex": 0, "consequences": ["They are the only issuers the cap limits today.", "Exempt banks are not capped now anyway.", "Merchants would likely pay more, not less."], "explanation": "The cap binds big issuers only. Lifting it would help them most."}, "proReasoning": "Investors ask who a rule binds today. Removing a cap helps exactly those it constrains.", "commonMistake": "Assuming a rule change helps every bank equally.", "mentalModel": "Lift a cap, help the capped."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the coffee chain. Most of your sales are small debit purchases.", "prompt": "What do you plan for?", "options": ["No change ever, since caps are permanent", "Higher debit costs if the cap falls", "Lower card costs from the ruling now"], "correctIndex": 1, "consequences": ["The cap is under legal challenge.", "Before the cap, debit averaged 44 cents a swipe.", "The ruling is paused, and it would raise costs, not cut them."], "explanation": "If the cap ends, debit fees could rise toward pre-cap levels. Budget for that risk."}, "proReasoning": "Merchants with many small debit sales feel the cap most. Plan a scenario where it disappears.", "commonMistake": "Treating a contested cap as permanent.", "mentalModel": "Plan for the rule to change."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks who decides how much a debit swipe costs a store.", "prompt": "What's the best answer?", "options": ["Each shopper sets it at checkout", "Stores pick any fee they like", "For big banks, a Fed rule caps it"], "correctIndex": 2, "consequences": ["Shoppers never see or set the fee.", "Stores pay the fee; they do not set it.", "Since 2011, 21 cents plus 0.05% at big issuers."], "explanation": "At banks with $10 billion or more, the Fed's rule caps debit interchange."}, "proReasoning": "Debit fees at big banks are set partly by regulation. That is why court rulings about them matter.", "commonMistake": "Thinking card fees are set at the register.", "mentalModel": "Rules set part of the toll."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$41f55c10-ecb6-593a-bca3-a8f615f64fb2$ml$::uuid, $ml$fintech$ml$, 9, 1, $ml${"id": "fintech-d9-c1", "title": "25 million cards on a new network", "lessonTitle": "The network everyone uses", "slot": 1, "type": "apply", "brief": {"headline": "After buying Discover, Capital One moved about 25 million debit cards off Mastercard onto the Discover network. Some cardholders then hit acceptance problems.", "kicker": "Apply day 9: owning a network is not the same as being accepted.", "fullText": "Regulators approved Capital One's purchase of Discover in April 2025, and with it came a card network. Owning the rails should lower Capital One's fees over time. By mid-2026 it had converted roughly 25 million debit cards to the Discover network and begun testing credit cards there. Its premium Venture X card stayed on Visa.\n\nSome cardholders reported trouble paying at small businesses, setting up subscriptions and using the cards abroad. Discover debit also had limited support for instant transfers to apps such as Venmo. Capital One said it was closing gaps at home and widening acceptance in Mexico, the Caribbean, Canada and the United Kingdom.\n\nDay 9 from the other side: a network gets its power from being accepted everywhere, and a new owner has to earn that.", "sources": [{"url": "https://www.paymentsjournal.com/after-moving-debit-cards-to-discover-capital-one-turns-to-credit-card-migration/", "label": "PaymentsJournal, After moving debit cards to Discover, Capital One turns to credit, Jul 2026"}, {"url": "https://www.pymnts.com/earnings/2026/capital-one-tests-moving-credit-cards-to-discover-network/", "label": "PYMNTS, Capital One tests moving credit cards to Discover network, Jul 2026"}, {"url": "https://www.emarketer.com/content/capital-one-hits-snags-with-moving-debit-cards-discover", "label": "eMarketer, Capital One hits snags with moving debit cards to Discover"}, {"url": "https://www.upi.com/Top_News/US/2025/04/18/Capital-One-Discover-merger-approved/6761745001368/", "label": "UPI, Capital One-Discover merger approved, Apr 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put Capital One's network move in order.", "steps": ["Capital One buys Discover and its network", "It moves debit cards off Mastercard", "Some users hit gaps in acceptance", "It works to widen acceptance abroad", "It tests moving credit cards next"], "explanation": "Debit went first. Credit cards wait until acceptance catches up."}, "numbers": {"kind": "numberSense", "prompt": "About how many million debit cards did Capital One move to the Discover network?", "min": 0, "max": 60, "value": 25, "unit": "M", "explanation": "Roughly 25 million. A big move, and it still showed where acceptance falls short."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing on Capital One's network team in 2026. They ask what the debit move taught.", "prompt": "What's your best answer?", "options": ["Cardholders never notice network changes", "Acceptance, not ownership, makes a network", "Owning a network removes all fees at once"], "correctIndex": 1, "consequences": ["Many cardholders noticed and complained.", "Users felt the gaps at small shops and abroad.", "Savings come over time, and only if cards work."], "explanation": "A network is valuable because everyone takes it. Ownership only pays off once acceptance is there."}, "proReasoning": "Explain network value as acceptance on both sides. Capital One owns rails that still need more merchants.", "commonMistake": "Treating network ownership as an instant win.", "mentalModel": "A network is its acceptance."}, "invest": {"call": {"kind": "theCall", "situation": "Capital One expects $2.5 billion in merger synergies by late 2027, partly from its own network.", "prompt": "What's the main risk to that?", "options": ["Discover runs out of card numbers", "Visa refuses to process its cards", "Cardholders leave if acceptance lags"], "correctIndex": 2, "consequences": ["Card numbers are not the constraint.", "Moved cards no longer use Visa anyway.", "Unhappy users can take their spending elsewhere."], "explanation": "Savings from owning the network depend on cards working wherever people shop."}, "proReasoning": "Investors test a network synergy against acceptance. Savings vanish if users switch away.", "commonMistake": "Counting network savings without checking acceptance.", "mentalModel": "Synergies need acceptance."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your app lets users link a debit card to move money instantly.", "prompt": "What does the switch mean for you?", "options": ["Test that switched cards work in your app", "Nothing, since all cards work the same", "Drop all Capital One users at once"], "correctIndex": 0, "consequences": ["Discover debit had limited instant transfer support.", "Networks differ in what they support.", "Dropping millions of users is rarely the answer."], "explanation": "A network change can break features your users rely on. Check before they hit the problem."}, "proReasoning": "Founders track network changes at big issuers. A silent switch can break a feature for millions.", "commonMistake": "Assuming every debit card behaves alike.", "mentalModel": "Networks differ; test the switch."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend's new Capital One debit card was declined at a small shop abroad.", "prompt": "What's the likely reason?", "options": ["Debit cards never work abroad", "Discover's network isn't taken everywhere yet", "Their account was frozen for possible fraud"], "correctIndex": 1, "consequences": ["Debit on bigger networks often works abroad.", "Discover's acceptance abroad trails Visa and Mastercard.", "Possible, but acceptance gaps were widely reported."], "explanation": "The card moved to a network with thinner acceptance abroad. The shop may not take it."}, "proReasoning": "When a card fails, ask which network it runs on. Acceptance differs by network.", "commonMistake": "Assuming every card works wherever another card does.", "mentalModel": "Ask which network it rides."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$a1a9ade5-d32f-5d2c-9305-1d746c102f45$ml$::uuid, $ml$fintech$ml$, 9, 2, $ml${"id": "fintech-d9-c2", "title": "The issuer's toll and the network's toll", "lessonTitle": "The network everyone uses", "slot": 2, "type": "connect", "brief": {"headline": "Each debit swipe pays interchange to the card's bank. The DOJ says Visa also charges over $7 billion a year to process the roughly 60% of US debit on its network.", "kicker": "Connect day 8 and day 9: two tolls on every debit swipe.", "fullText": "On day 8 you saw that part of each swipe fee is interchange, paid to the bank that issued the card. On day 9 you met the network. The Justice Department, suing Visa in September 2024, said about 60% of US debit transactions run on Visa's network and that Visa charges over $7 billion a year to process them.\n\nSo a debit swipe feeds two parties: the issuing bank through interchange, and the network through processing fees. The DOJ alleged Visa penalizes merchants and banks that route payments elsewhere.", "sources": [{"url": "https://www.everycrsreport.com/reports/R41913.html", "label": "Congressional Research Service, Regulation of debit interchange fees"}, {"url": "https://6abc.com/15349714", "label": "AP via 6abc, DOJ sues Visa over debit, Sep 2024"}]}, "evidence": {"kind": "faceOff", "prompt": "Who receives interchange on a debit swipe?", "left": {"name": "The card-issuing bank", "note": "Issued the card to the shopper"}, "right": {"name": "The network, like Visa", "note": "Runs the rails the swipe travels on"}, "correctIndex": 0, "explanation": "Interchange goes to the issuer. The network earns its own processing fees."}, "numbers": {"kind": "numberSense", "prompt": "The DOJ says Visa charges over how many billion dollars a year to process US debit?", "min": 0, "max": 20, "value": 7, "unit": "B", "explanation": "Over $7 billion a year, on top of the interchange that goes to issuers."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In a payments interview, you're asked who earns on a debit swipe.", "prompt": "What's your best answer?", "options": ["Only Visa earns anything at all on a swipe", "Only the store earns, from the sale", "The issuer gets interchange; the network, fees"], "correctIndex": 2, "consequences": ["Issuers collect interchange too.", "The store pays the tolls rather than earning them.", "Two tolls, two collectors, named precisely."], "explanation": "Interchange flows to the issuer. Processing fees flow to the network."}, "proReasoning": "Payments interviewers check that you can split the swipe fee. Issuer and network earn separately.", "commonMistake": "Calling the whole swipe fee a network fee.", "mentalModel": "Two tolls, two collectors."}, "invest": {"call": {"kind": "theCall", "situation": "The DOJ case targets Visa's debit processing, not banks' interchange.", "prompt": "Whose revenue is most at stake?", "options": ["Visa's, from debit processing fees", "Issuing banks', from interchange", "Merchants', from store sales"], "correctIndex": 0, "consequences": ["The suit centers on over $7 billion of Visa fees.", "Interchange is not the target of this case.", "Merchants pay the fees rather than earning them."], "explanation": "The case is about Visa's conduct in debit. Its processing revenue is what is at stake."}, "proReasoning": "Investors map a lawsuit to the revenue line it threatens. Here it is network processing fees.", "commonMistake": "Assuming every payments firm is equally exposed to the case.", "mentalModel": "Map the suit to the revenue line."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup wants merchants to route debit payments over a cheaper network.", "prompt": "What headwind does the DOJ describe?", "options": ["Shoppers refusing to tap their cards", "Penalties for those who route elsewhere", "A law banning other debit networks"], "correctIndex": 1, "consequences": ["Shoppers rarely see which network runs.", "The DOJ alleged Visa penalizes merchants and banks that do.", "Other networks are legal; the issue is incentives."], "explanation": "The suit alleges Visa makes routing elsewhere costly. That shapes any rival network plan."}, "proReasoning": "Founders challenging a dominant network price in the incentives it uses to keep volume.", "commonMistake": "Assuming a cheaper price alone wins routing.", "mentalModel": "Price in the incumbent incentives."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks a store's swipe fee all goes to Visa.", "prompt": "What's the best answer?", "options": ["Yes, Visa keeps every single cent of it", "It goes to the government as a tax", "A big part goes to the bank that issued it"], "correctIndex": 2, "consequences": ["The issuing bank collects interchange.", "Swipe fees are private charges, not taxes.", "Interchange goes to the issuer; Visa earns processing fees."], "explanation": "The swipe fee is split. Interchange goes to the issuer, and the network takes its own fees."}, "proReasoning": "Split the swipe fee into its pieces. Most people never learn that their own bank gets a share.", "commonMistake": "Thinking the logo on the card collects the whole fee.", "mentalModel": "The logo is not the only collector."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$e10fca09-a83d-520f-90ff-e67dffbe0ae8$ml$::uuid, $ml$fintech$ml$, 9, 3, $ml${"id": "fintech-d9-c3", "title": "Starting a network from zero", "lessonTitle": "The network everyone uses", "slot": 3, "type": "decide", "brief": {"headline": "You run a startup that wants to launch a new US debit network. About 60% of US debit already runs on Visa, the DOJ says.", "kicker": "Decide how a new network gets its first side to join.", "fullText": "Networks grow stronger with use. Merchants accept a card because shoppers carry it, and banks issue it because merchants accept it. The Justice Department says about 60% of US debit transactions run on Visa's network.\n\nIt also alleges that Visa penalizes merchants and banks that use other processing options, and pays potential competitors to partner with it instead. Your network has no merchants and no issuing banks yet.", "sources": [{"url": "https://6abc.com/15349714", "label": "AP via 6abc, DOJ sues Visa over debit, Sep 2024"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why is a new debit network so hard to start?", "options": ["Merchants and banks each wait for the other", "New debit networks are illegal in the US", "Shoppers dislike new card logos"], "correctIndex": 0, "explanation": "Each side joins for the other. With neither on board, there is no reason to start."}, "numbers": {"kind": "numberSense", "prompt": "If about 60% of US debit runs on Visa, what share runs on everything else?", "min": 0, "max": 100, "value": 40, "unit": "%", "explanation": "About 40%, split among all the other networks."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're weighing an offer from the new debit network startup.", "prompt": "What do you ask its founders?", "options": ["How they will win banks and merchants at once", "How fancy and modern the card design will look", "Whether the office has free snacks"], "correctIndex": 0, "consequences": ["That is the problem every new network must solve.", "Design matters little next to acceptance.", "Perks say nothing about survival."], "explanation": "A network lives or dies on getting both sides on board. Ask how they will do it."}, "proReasoning": "Before joining a network startup, ask about its plan for both sides. It is the whole game.", "commonMistake": "Judging a network startup by its product polish.", "mentalModel": "Ask how both sides join."}, "invest": {"call": {"kind": "theCall", "situation": "A new debit network signs its first big issuing bank.", "prompt": "Why does that matter so much?", "options": ["It ends Visa's lead overnight", "Issued cards give merchants a reason to join", "Banks pay networks huge fees just to sign up"], "correctIndex": 1, "consequences": ["About 60% of debit is still on Visa.", "Cards in wallets pull in merchants.", "The value is the cards, not a fee."], "explanation": "One side brings the other. A big issuer puts cards in wallets, which draws merchants."}, "proReasoning": "Investors look for the first side that tips a network. A big issuer can start the loop.", "commonMistake": "Expecting one deal to topple an incumbent.", "mentalModel": "One side pulls the other."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the startup. A big incumbent offers you a lucrative partnership instead of competing.", "prompt": "What do you weigh?", "options": ["Only the size of the payment on offer", "Only what your engineers prefer", "Cash now against ever becoming a rival"], "correctIndex": 2, "consequences": ["The payment is half of the trade-off.", "Engineering taste is not the strategic question.", "The DOJ says such deals turn rivals into partners."], "explanation": "The DOJ alleges Visa pays potential competitors to partner. Taking the deal can mean giving up the fight."}, "proReasoning": "Founders ask what a partnership costs in independence. A good deal today can end the rivalry for good.", "commonMistake": "Judging the offer only by its price tag.", "mentalModel": "Price what you give up."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why there aren't more card networks.", "prompt": "What's the best answer?", "options": ["Each side waits for the other to join first", "Only two companies may legally run one", "Nobody has thought of building one"], "correctIndex": 0, "consequences": ["Merchants want cardholders; banks want merchants.", "Several networks exist; most are small.", "Plenty have tried; acceptance is the barrier."], "explanation": "A network is useful only once both sides use it. That makes new ones very hard to start."}, "proReasoning": "Network businesses have a chicken-and-egg start. Once one side is big, the other follows.", "commonMistake": "Thinking dominance comes only from a better product.", "mentalModel": "Networks have a chicken-and-egg start."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$5a5e4dc7-b5c8-5923-9c37-bdaeb657f865$ml$::uuid, $ml$fintech$ml$, 10, 1, $ml${"id": "fintech-d10-c1", "title": "20 billion in a month", "lessonTitle": "Instant payments by the numbers", "slot": 1, "type": "apply", "brief": {"headline": "In August 2025, India's UPI processed 20.01 billion payments worth ₹24.85 lakh crore. It was the first month above 20 billion, an average of 645 million a day.", "kicker": "Apply day 10: read an instant rail by its numbers.", "fullText": "UPI, India's instant payment system, grew 34% in count from 14.9 billion payments in August 2024, and 21% in value. Daily averages were 645 million payments and ₹80,177 crore.\n\nCompare day 10's US numbers. The Clearing House's RTP network processed 31.7 million payments in October 2024, across the whole month. At August's pace, UPI handled that many in a little over an hour.\n\nDivide value by count, as on day 4: ₹24.85 lakh crore over 20.01 billion is about ₹1,240 a payment. That points to everyday spending.", "sources": [{"url": "https://www.businesstoday.in/latest/economy/story/upi-crosses-20-billion-monthly-transactions-for-first-time-in-august-value-hits-rs2485-lakh-crore-491955-2025-09-01", "label": "Business Today, UPI crosses 20 billion monthly transactions, Sep 2025"}, {"url": "https://paymentsdive.com/news/real-time-payments-network-transacion-limit-increase/734710", "label": "Payments Dive, RTP raises transaction limit to $10 million, Dec 2024"}]}, "evidence": {"kind": "multipleChoice", "prompt": "UPI averaged about ₹1,240 a payment. What does that suggest?", "options": ["Mostly small, everyday payments", "Mostly large business transfers", "Mostly payments between banks"], "correctIndex": 0, "explanation": "A small average size means everyday use. Count matters more than value on a rail like this."}, "numbers": {"kind": "numberSense", "prompt": "On an average day in August 2025, how many million UPI payments went through?", "min": 0, "max": 1000, "value": 645, "unit": "M", "explanation": "About 645 million a day, against 31.7 million a month on RTP in October 2024."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a US payments firm. They ask for one fact about instant payments abroad.", "prompt": "Which fact lands best?", "options": ["India has a very large population", "Instant payments are popular in some places", "UPI passed 20 billion payments in August 2025"], "correctIndex": 2, "consequences": ["True, but it says nothing about the rail.", "Too vague to show you follow the field.", "One sourced number with a date beats vague claims."], "explanation": "A precise number shows you track payments globally. UPI is the standard example."}, "proReasoning": "Bring one dated, sourced number. UPI at 20 billion a month shows what instant rails can reach.", "commonMistake": "Speaking in generalities about global payments.", "mentalModel": "One dated number beats ten adjectives."}, "invest": {"call": {"kind": "theCall", "situation": "UPI's count grew 34% in a year, while its value grew 21%.", "prompt": "What does count outgrowing value tell you?", "options": ["The average payment is getting smaller", "People are sending far bigger payments", "Nothing, since the two always match"], "correctIndex": 0, "consequences": ["Smaller tickets mean UPI is reaching everyday spending.", "Value grew slower than count, so sizes fell.", "Count and value often grow at different rates."], "explanation": "When count grows faster than value, each payment is smaller on average. Usage is spreading to small purchases."}, "proReasoning": "Investors compare count growth with value growth. The gap tells you whether payments are getting bigger or smaller.", "commonMistake": "Reading only one growth number.", "mentalModel": "Compare count growth with value growth."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're sizing a fraud-screening tool for an instant rail like UPI.", "prompt": "Which number matters most?", "options": ["The number of banks on the rail", "Payments per day, since each needs a check", "Total value per month, and nothing else"], "correctIndex": 1, "consequences": ["Banks are customers; payments are the load.", "645 million daily checks sets your scale.", "Value matters, but each payment needs screening."], "explanation": "A screening tool runs once per payment. Count, not value, sets the load."}, "proReasoning": "Founders size infrastructure by the event count it must handle. On UPI, that is hundreds of millions a day.", "commonMistake": "Sizing a per-payment tool by total value.", "mentalModel": "Size by the count you must handle."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how UPI compares with the US RTP network.", "prompt": "What's the best answer?", "options": ["They handle about the same number each month", "RTP handles far more payments", "UPI does RTP's monthly count in about an hour"], "correctIndex": 2, "consequences": ["UPI handles hundreds of times more.", "RTP is much smaller by count.", "645 million a day against 31.7 million a month."], "explanation": "UPI processed 645 million payments a day; RTP processed 31.7 million in a month."}, "proReasoning": "Turn two big numbers into one comparison people can feel. An hour against a month does that.", "commonMistake": "Listing numbers without comparing them.", "mentalModel": "Make the comparison feel real."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$f6234acc-6b6d-5d47-85f8-fe172fa77176$ml$::uuid, $ml$fintech$ml$, 10, 2, $ml${"id": "fintech-d10-c2", "title": "Open when others are closed", "lessonTitle": "Instant payments by the numbers", "slot": 2, "type": "connect", "brief": {"headline": "RTP and FedNow settle around the clock, while FedACH closes on weekends and holidays. On RTP, 42% of payments happen overnight, on weekends or on holidays.", "kicker": "Connect day 7 and day 10: always-on rails get used off-hours.", "fullText": "On day 7 you saw that the rail sets the speed, the cost and the hours. FedACH is closed on weekends and holidays, while RTP and FedNow never close. On day 10 you saw what happens when a rail stays open: 42% of RTP transactions happen overnight, on weekends or on holidays.\n\nThat demand existed all along. A batch rail simply could not serve it.", "sources": [{"url": "https://en.wikipedia.org/wiki/FedNow", "label": "FedNow"}, {"url": "https://paymentsdive.com/news/real-time-payments-network-transacion-limit-increase/734710", "label": "Payments Dive, RTP raises transaction limit to $10 million, Dec 2024"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this payment need an instant rail, or can FedACH handle it too?", "buckets": ["Instant rail only", "FedACH can too"], "items": [{"text": "A payout at 2 am on a Sunday", "bucket": 0}, {"text": "A transfer on a public holiday", "bucket": 0}, {"text": "A Saturday payout to a gig worker", "bucket": 0}, {"text": "Payroll sent Tuesday for Thursday", "bucket": 1}, {"text": "A bill paid on a weekday", "bucket": 1}], "explanation": "Anything outside business days needs a rail that never closes."}, "numbers": {"kind": "numberSense", "prompt": "If 42% of RTP payments happen off-hours, what share happen during business hours?", "min": 0, "max": 100, "value": 58, "unit": "%", "explanation": "58%. Nearly half of the demand would have nowhere to go on a batch rail."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In a bank interview, you're asked why instant rails matter if ACH works fine.", "prompt": "What's your best answer?", "options": ["42% of RTP payments happen when ACH is shut", "Instant rails are newer, so they are better", "ACH will be switched off next year"], "correctIndex": 0, "consequences": ["A number that shows real off-hours demand.", "Newness alone is not an argument.", "ACH carried 35.2 billion payments in 2025."], "explanation": "The 42% shows demand that batch rails cannot serve. It answers the question with data."}, "proReasoning": "Quote the 42%. It turns a vague claim about speed into evidence of real demand.", "commonMistake": "Arguing for instant rails on novelty.", "mentalModel": "Demand shows up when the rail is open."}, "invest": {"call": {"kind": "theCall", "situation": "An app's weekend payout feature runs on RTP.", "prompt": "Why could that edge last?", "options": ["Weekend payouts are free to run", "Batch rails cannot pay out on weekends", "RTP is the only instant rail in America"], "correctIndex": 1, "consequences": ["Instant payouts are not free.", "Rivals on batch rails must switch rails to match.", "FedNow also runs 24/7, and ACH exists."], "explanation": "The feature depends on the rail. Rivals cannot copy it without changing rails."}, "proReasoning": "Investors value features rooted in infrastructure. They are slower for rivals to copy.", "commonMistake": "Treating any feature as easy to copy.", "mentalModel": "Rail-based edges last longer."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a payroll startup. Clients want pay to land on Saturday mornings.", "prompt": "Which rail do you use?", "options": ["FedACH, sent on Saturday", "A paper check mailed on Friday", "RTP or FedNow, open around the clock"], "correctIndex": 2, "consequences": ["FedACH is closed on weekends.", "A check would not be money on Saturday.", "They settle on Saturday, as promised."], "explanation": "Saturday settlement needs a rail open on Saturday."}, "proReasoning": "Founders promise only what the rail can deliver. Off-hours promises need off-hours rails.", "commonMistake": "Promising weekend pay on a weekday rail.", "mentalModel": "Promise what the rail can do."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks who sends payments at 3 am.", "prompt": "What's the best answer?", "options": ["Many: 42% of RTP runs outside business hours", "Nobody, it is only for show", "Only banks testing their systems overnight"], "correctIndex": 0, "consequences": ["Nights, weekends and holidays add up to 42%.", "The data shows heavy real use.", "Real people and businesses use it."], "explanation": "People need money when they need it. Nearly half of RTP use comes outside business hours."}, "proReasoning": "Money needs do not keep office hours. Open rails reveal how much demand was waiting.", "commonMistake": "Assuming payments only matter in business hours.", "mentalModel": "Money needs keep no office hours."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$462c2130-330c-5283-8861-e5d5edaabc86$ml$::uuid, $ml$fintech$ml$, 10, 3, $ml${"id": "fintech-d10-c3", "title": "The $10 million instant payment", "lessonTitle": "Instant payments by the numbers", "slot": 3, "type": "decide", "brief": {"headline": "On February 9, 2025, RTP raised its per-payment limit to $10 million. It had been $100,000 until April 2022, then $1 million.", "kicker": "Decide when a big payment should go instant.", "fullText": "The Clearing House's RTP network raised its limit from $100,000 to $1 million in April 2022, and to $10 million on February 9, 2025. About 285,000 businesses a month send RTP payments. By 2025, over a thousand financial institutions were live on FedNow, launched in July 2023.\n\nYou run treasury at a mid-size manufacturer. A $4 million supplier payment is due on a Saturday.", "sources": [{"url": "https://paymentsdive.com/news/real-time-payments-network-transacion-limit-increase/734710", "label": "Payments Dive, RTP raises transaction limit to $10 million, Dec 2024"}, {"url": "https://en.wikipedia.org/wiki/FedNow", "label": "FedNow"}]}, "evidence": {"kind": "buildChain", "prompt": "Put RTP's rise in order.", "steps": ["Large banks launch RTP in 2017", "The limit is $100,000 per payment", "The limit rises to $1 million in April 2022", "The limit rises to $10 million in February 2025", "Big business payments can now go instant"], "explanation": "Each limit increase opened RTP to bigger payments, from consumers to large firms."}, "numbers": {"kind": "numberSense", "prompt": "RTP's limit went from $100,000 to $10 million. How many times larger?", "min": 0, "max": 250, "value": 100, "unit": "x", "explanation": "A hundred times larger in under three years."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a treasury analyst. A $4 million supplier payment must land on a Saturday.", "prompt": "What do you propose?", "options": ["Split it into forty $100,000 payments", "Send it over RTP, under the $10 million limit", "Use FedACH and send it first thing Saturday"], "correctIndex": 1, "consequences": ["No need to split; the limit is now $10 million.", "It fits the limit and settles on Saturday.", "FedACH is closed on weekends."], "explanation": "Since February 2025, RTP can carry it in one payment, any day."}, "proReasoning": "Treasury teams track rail limits. A change from $1 million to $10 million changes which payments qualify.", "commonMistake": "Working around a limit that no longer applies.", "mentalModel": "Know the current limit."}, "invest": {"call": {"kind": "theCall", "situation": "RTP's limit rose 100 times in under three years.", "prompt": "Which use does that open up most?", "options": ["Small payments between friends", "Cash withdrawals at ATMs", "Large payments between businesses"], "correctIndex": 2, "consequences": ["Small payments already fit under $100,000.", "ATMs are not part of RTP.", "Big business flows needed the higher limit."], "explanation": "Higher limits matter to big payers. Large business flows can now go instant."}, "proReasoning": "Investors read limit increases as market expansion. Each step lets bigger flows onto the rail.", "commonMistake": "Ignoring technical limits as a growth driver.", "mentalModel": "Higher limits, bigger market."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run treasury software for mid-size firms.", "prompt": "What does the $10 million limit let you build?", "options": ["Instant, any-day supplier payments", "Card rewards for corporate buyers", "A new check-printing service"], "correctIndex": 0, "consequences": ["Large invoices can now settle on any day.", "Rewards are a card feature, not RTP.", "Checks go the other way from instant."], "explanation": "Most supplier payments now fit under the limit. Software can offer them instantly, any day."}, "proReasoning": "Founders turn rail changes into features quickly. A tenfold limit increase is a product opening.", "commonMistake": "Missing a product opening hidden in a rail rule.", "mentalModel": "Rail rules hide product openings."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a payment limit matters to anyone.", "prompt": "What's the best answer?", "options": ["It only matters to lottery winners", "Big payments couldn't use the rail before", "Limits decide who may own or run a bank"], "correctIndex": 1, "consequences": ["Businesses send big payments every day.", "Raising it opened RTP to large business payments.", "Limits govern payments, not ownership."], "explanation": "A low limit keeps large payments off the rail. Raising it brings them on."}, "proReasoning": "Limits shape who a rail serves. Lift the limit, and new users arrive.", "commonMistake": "Seeing limits as a technical footnote.", "mentalModel": "Limits decide who can ride."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$9c06cd2c-0657-555c-8f99-593a54502481$ml$::uuid, $ml$fintech$ml$, 11, 1, $ml${"id": "fintech-d11-c1", "title": "The UK makes banks pay for scams", "lessonTitle": "Money you can't take back", "slot": 1, "type": "apply", "brief": {"headline": "Since October 7, 2024, UK payment firms must refund victims of push payment scams up to £85,000. The sending and receiving firms split the cost 50:50.", "kicker": "Apply day 11: make firms pay, and they fight scams before money leaves.", "fullText": "Authorised push payment fraud is when a victim is tricked into sending money themselves. Under the UK's rules for Faster Payments and CHAPS, the sending firm must reimburse within five business days of the report. It can pause the clock to investigate, but must close the claim within 35 business days, and it may apply an excess of up to £100. The receiving firm pays back half.\n\nThe regulator had proposed a £415,000 cap before settling on £85,000. Firms need not refund customers who acted fraudulently or with gross negligence, but vulnerable customers are shielded from that exception and from the excess.\n\nCompare day 11: the CFPB's US Zelle suit alleged victims were often denied relief, then was dropped. The UK chose to make payment firms pay.", "sources": [{"url": "https://www.freshfields.com/en/our-thinking/briefings/2024/09/authorised-push-payment-fraud-a-new-mandatory-reimbursement-regime-for-uk-psps", "label": "Freshfields, APP fraud: a new mandatory reimbursement regime, Sep 2024"}, {"url": "https://www.dlapiper.com/insights/publications/2024/09/psr-confirms-app-fraud-reimbursement-level-to-be-reduced", "label": "DLA Piper, PSR confirms APP fraud reimbursement level, Sep 2024"}, {"url": "https://fortune.com/2024/12/20/cfpb-sues-jpmorgan-bank-of-america-alleged-zelle-fraud", "label": "Fortune, CFPB sues JPMorgan, Bank of America and Wells Fargo over Zelle, Dec 2024"}, {"url": "https://www.crowdfundinsider.com/2025/03/237009-cfpb-drops-zelle-fraud-lawsuit-against-major-us-banking-institutions/", "label": "Crowdfund Insider, CFPB drops Zelle lawsuit, Mar 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each item part of the UK refund rules?", "buckets": ["In the rules", "Not in the rules"], "items": [{"text": "Refunds of up to £85,000", "bucket": 0}, {"text": "The receiving firm pays half", "bucket": 0}, {"text": "An excess of up to £100", "bucket": 0}, {"text": "Refunds on international payments", "bucket": 1}, {"text": "Refunds for gross negligence", "bucket": 1}], "explanation": "The rules cover Faster Payments and CHAPS, with limits and exceptions."}, "numbers": {"kind": "numberSense", "prompt": "The regulator first proposed a cap of how many thousand pounds, before settling on £85,000?", "min": 0, "max": 1000, "value": 415, "unit": "K", "explanation": "£415,000, cut to £85,000, which matched the UK deposit compensation limit at the time."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a UK bank's fraud team. They ask what changed in October 2024.", "prompt": "What's your best answer?", "options": ["Banks now share the cost of scam refunds", "Instant payments were banned in the UK", "Victims must now pay the banks back"], "correctIndex": 0, "consequences": ["Sending and receiving firms split refunds 50:50.", "Faster Payments still runs; the rules cover it.", "It is the reverse: firms refund victims."], "explanation": "Scam losses moved onto the firms. That makes prevention a direct cost saving."}, "proReasoning": "Fraud teams now sit closer to the profit line. Every scam stopped is a refund not paid.", "commonMistake": "Describing the rules as a ban instead of a cost shift.", "mentalModel": "Who pays for scams shapes who fights them."}, "invest": {"call": {"kind": "theCall", "situation": "A UK bank's customers lose more each year to push payment scams.", "prompt": "Why does that now hit the bank's results?", "options": ["It must stop offering Faster Payments", "It must refund victims up to £85,000", "Regulators fine it for each customer"], "correctIndex": 1, "consequences": ["Faster Payments stays; refunds apply to it.", "Refunds, split with receiving firms, are a direct cost.", "The rules are about refunds, not per-customer fines."], "explanation": "Since October 2024, scam losses flow back to the firms. They show up in costs."}, "proReasoning": "Investors watch who carries fraud losses. A rule change can move them onto the bank overnight.", "commonMistake": "Treating customer fraud as the customer's problem.", "mentalModel": "Follow who carries the loss."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells scam warnings that run before a payment is sent.", "prompt": "Where is demand strongest?", "options": ["Shops that only take cash payments", "Firms that send no payments", "UK banks now paying for scam losses"], "correctIndex": 2, "consequences": ["Cash shops have no push payments to protect.", "No payments, no scam refunds.", "Each scam stopped saves a refund they would owe."], "explanation": "When banks carry scam losses, tools that stop scams save them money directly."}, "proReasoning": "Founders sell to whoever pays for the problem. In the UK, that is now the banks.", "commonMistake": "Selling to whoever suffers instead of whoever pays.", "mentalModel": "Sell to whoever pays."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend in London was tricked into sending £2,000 to a scammer by bank transfer.", "prompt": "What will likely happen?", "options": ["A refund, minus any excess, within days", "Nothing, since they sent it themselves", "A refund only if police catch the scammer"], "correctIndex": 0, "consequences": ["Unless grossly negligent, they should be refunded.", "The UK rules cover payments victims sent themselves.", "Refunds do not depend on catching anyone."], "explanation": "UK rules require refunds for push payment scams, with limited exceptions."}, "proReasoning": "In the UK, being tricked into paying no longer means losing the money. The firms carry most of the cost.", "commonMistake": "Assuming authorised payments can never be refunded.", "mentalModel": "The rules decide who eats the loss."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$3a906c1c-ccda-55ce-8c63-e8805effd77a$ml$::uuid, $ml$fintech$ml$, 11, 2, $ml${"id": "fintech-d11-c2", "title": "Always open, for scammers too", "lessonTitle": "Money you can't take back", "slot": 2, "type": "connect", "brief": {"headline": "On RTP, 42% of payments happen overnight, on weekends or on holidays. The CFPB's Zelle suit cited about $870 million in fraud losses on fast payments.", "kicker": "Connect day 10 and day 11: speed that helps users helps scammers.", "fullText": "On day 10 you saw that instant rails serve real demand: 42% of RTP payments come outside business hours. On day 11 you saw the other side. When a payment settles in seconds, a scam victim has almost no time to stop it.\n\nThe CFPB alleged that big banks rushed Zelle to market without adequate protections, citing about $870 million in losses. The case was dropped in March 2025, but the problem it described remains: the faster money moves, the more prevention matters.", "sources": [{"url": "https://paymentsdive.com/news/real-time-payments-network-transacion-limit-increase/734710", "label": "Payments Dive, RTP raises transaction limit to $10 million, Dec 2024"}, {"url": "https://fortune.com/2024/12/20/cfpb-sues-jpmorgan-bank-of-america-alleged-zelle-fraud", "label": "Fortune, CFPB sues JPMorgan, Bank of America and Wells Fargo over Zelle, Dec 2024"}, {"url": "https://www.crowdfundinsider.com/2025/03/237009-cfpb-drops-zelle-fraud-lawsuit-against-major-us-banking-institutions/", "label": "Crowdfund Insider, CFPB drops Zelle lawsuit, Mar 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how an instant scam plays out.", "steps": ["A scammer contacts a victim on a Sunday night", "The victim sends money on an instant rail", "The payment settles within seconds", "The scammer moves the money on", "The victim reports it, too late to stop"], "explanation": "Instant settlement leaves no window to cancel. Prevention has to happen before the payment."}, "numbers": {"kind": "numberSense", "prompt": "The CFPB cited about how many million dollars in Zelle fraud losses?", "min": 0, "max": 2000, "value": 870, "unit": "M", "explanation": "About $870 million. Fast money moved to scammers just as fast."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join an instant payments fraud team. Many alerts arrive at night and on weekends.", "prompt": "How should the team staff?", "options": ["Check alerts each Monday morning", "Cover off-hours, since the rail never closes", "Work weekdays only, just like the ACH team"], "correctIndex": 1, "consequences": ["By Monday, instant money is long gone.", "42% of RTP activity happens off-hours.", "Scams do not wait for Monday."], "explanation": "An always-on rail needs always-on defenses."}, "proReasoning": "Fraud teams on instant rails match the rail's hours. Automated checks and on-call staff cover the gaps.", "commonMistake": "Staffing an instant rail like a batch one.", "mentalModel": "Defend the hours the rail is open."}, "invest": {"call": {"kind": "theCall", "situation": "A bank pushes instant payments hard, around the clock.", "prompt": "What cost do you watch?", "options": ["The cost of printing paper checks", "Branch rent in big cities", "Fraud losses and prevention spending"], "correctIndex": 2, "consequences": ["Checks are a shrinking cost here.", "Branches have little to do with instant fraud.", "Faster money raises the stakes of each scam."], "explanation": "Instant volume brings instant fraud. Watch losses and what the bank spends to prevent them."}, "proReasoning": "Investors pair instant payment growth with fraud costs. Both rise together unless prevention keeps up.", "commonMistake": "Counting instant volume growth without its fraud cost.", "mentalModel": "Instant volume carries instant risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your scam-detection tool must decide in under a second.", "prompt": "Why so fast?", "options": ["Instant payments cannot be recalled after", "Users enjoy watching fast loading spinners", "Slow tools cost more to host"], "correctIndex": 0, "consequences": ["Once settled, the money is gone.", "The point is stopping fraud, not looks.", "Cost is minor next to losses."], "explanation": "On instant rails, the only chance to stop a scam is before settlement."}, "proReasoning": "Founders on instant rails design for the moment before settlement. After that, it is recovery, not prevention.", "commonMistake": "Building checks that run after the money has moved.", "mentalModel": "Stop it before it settles."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why their bank asks whether they know the person before a transfer.", "prompt": "What's the best answer?", "options": ["It is required for every card swipe", "Instant money is hard to get back once sent", "The bank is curious about their friends"], "correctIndex": 1, "consequences": ["It applies to transfers, not swipes.", "The question is a last chance to stop a scam.", "It is about fraud, not curiosity."], "explanation": "On fast rails, warnings before payment are the main defense against scams."}, "proReasoning": "Those annoying warnings exist because instant payments are final. They are the last line of defense.", "commonMistake": "Treating payment warnings as needless friction.", "mentalModel": "Warnings come first because refunds rarely do."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$322c246d-a85b-5018-97a8-386f84078a9f$ml$::uuid, $ml$fintech$ml$, 11, 3, $ml${"id": "fintech-d11-c3", "title": "The suit was dropped. Now what?", "lessonTitle": "Money you can't take back", "slot": 3, "type": "decide", "brief": {"headline": "The CFPB sued three big banks and Zelle's operator in December 2024 over fraud losses, then dropped the case in March 2025. You run fraud strategy at a mid-size bank on Zelle.", "kicker": "Decide whether a dropped case changes your fraud plans.", "fullText": "On December 20, 2024, the CFPB sued JPMorgan Chase, Bank of America, Wells Fargo and Early Warning Services, which runs Zelle. It alleged the banks launched Zelle without adequate protections and often denied fraud victims relief, citing about $870 million in losses. Zelle called the suit legally and factually flawed. On March 4, 2025, the CFPB dropped the case with prejudice.\n\nThe case is gone. The scams it described may not be.", "sources": [{"url": "https://fortune.com/2024/12/20/cfpb-sues-jpmorgan-bank-of-america-alleged-zelle-fraud", "label": "Fortune, CFPB sues JPMorgan, Bank of America and Wells Fargo over Zelle, Dec 2024"}, {"url": "https://www.crowdfundinsider.com/2025/03/237009-cfpb-drops-zelle-fraud-lawsuit-against-major-us-banking-institutions/", "label": "Crowdfund Insider, CFPB drops Zelle lawsuit, Mar 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the Zelle case. Tap it.", "statements": ["The CFPB sued in December 2024.", "It cited about $870 million in fraud losses.", "A court ordered the banks to repay victims."], "fakeIndex": 2, "explanation": "The CFPB dropped the case with prejudice in March 2025. No court ordered repayment."}, "numbers": {"kind": "numberSense", "prompt": "How many big banks did the CFPB sue alongside Zelle's operator?", "min": 0, "max": 10, "value": 3, "unit": "banks", "explanation": "Three: JPMorgan Chase, Bank of America and Wells Fargo."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager says the dropped suit means fraud work can slow down.", "prompt": "How do you respond?", "options": ["Agree, since the legal risk has now gone away", "Shut down the fraud team to save money", "Keep going: the scams didn't end with the case"], "correctIndex": 2, "consequences": ["Legal risk can return; losses stay either way.", "That invites the losses the suit described.", "Customer losses and trust are still at stake."], "explanation": "A dropped case removes one risk. It does not stop the scams themselves."}, "proReasoning": "Strong fraud people separate legal risk from fraud risk. The second stays when the first goes.", "commonMistake": "Letting a legal outcome set the fraud budget.", "mentalModel": "Legal risk and fraud risk are different."}, "invest": {"call": {"kind": "theCall", "situation": "The CFPB dropped the Zelle suit with prejudice, three months after filing.", "prompt": "How do you read the regulatory risk?", "options": ["Lower for now, but it can swing back", "Gone for good across every agency", "Higher than before the suit"], "correctIndex": 0, "consequences": ["Enforcement depends on who runs the agency.", "Other agencies and future leaders can act.", "The case was dropped, not escalated."], "explanation": "The suit came and went within months. Enforcement can change direction with leadership."}, "proReasoning": "Investors treat enforcement as cyclical. A dropped case lowers risk today, not forever.", "commonMistake": "Treating one dropped case as permanent relief.", "mentalModel": "Enforcement swings."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run fraud strategy at the bank. A board member wants to cut the anti-scam budget.", "prompt": "What do you argue?", "options": ["Move the money into marketing", "Scams still cost customers and their trust", "Cut it, since the lawsuit has been dropped"], "correctIndex": 1, "consequences": ["Marketing cannot fix lost trust.", "Losing customers to scams costs the bank either way.", "The losses that drove the suit have not vanished."], "explanation": "The suit was about real losses. Those losses hurt customers and the bank, case or no case."}, "proReasoning": "Fraud leaders defend budgets with customer losses, not with lawsuits. Losses are the lasting reason.", "commonMistake": "Tying fraud spending to the legal calendar.", "mentalModel": "Defend the budget with losses."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether the CFPB won its Zelle case.", "prompt": "What's the best answer?", "options": ["Yes, the banks paid $870 million", "The case is still going on today", "No, it dropped the case in March 2025"], "correctIndex": 2, "consequences": ["$870 million was the loss cited, not a payment.", "It ended in March 2025.", "It was dropped with prejudice, so it cannot be refiled."], "explanation": "The CFPB dropped the case with prejudice. No court ruled for either side."}, "proReasoning": "Read how a case ended, not just how it began. Many headlines cover filings that later go nowhere.", "commonMistake": "Assuming a lawsuit means someone won.", "mentalModel": "Check how the case ended."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$ddd2c0a8-19ac-5ad1-928b-fc5448b7c139$ml$::uuid, $ml$fintech$ml$, 12, 1, $ml${"id": "fintech-d12-c1", "title": "China's own cross-border rail", "lessonTitle": "Cut off from Swift", "slot": 1, "type": "apply", "brief": {"headline": "China's CIPS, launched in October 2015, handled 175 trillion yuan of cross-border payments in 2024, up 43%. It reaches 185 countries and regions.", "kicker": "Apply day 12: control of the plumbing invites alternatives.", "fullText": "CIPS, China's Cross-Border Interbank Payment System, handles payments in yuan. By the end of 2024 it had processed about 600 trillion yuan in total since launch. More than half of its participants were outside China, among more than 4,800 banking institutions it reaches.\n\nDay 12 showed why such systems matter. In March 2022 the EU ordered seven Russian banks cut off from Swift, and Swift, headquartered in Belgium, is subject to EU law. Whoever controls a payment network can cut a bank off. A network governed elsewhere answers to a different rulebook.", "sources": [{"url": "https://english.shanghai.gov.cn/en-FinancialReformandInnovation/20250108/0d5502fd008549f1bb306f5ccf1ffe7a.html", "label": "Shanghai government, RMB globalization grows with expanding CIPS business, Jan 2025"}, {"url": "https://www.kelleydrye.com/viewpoints/blogs/trade-and-manufacturing-monitor/eu-imposes-measure-to-remove-7-russian-banks-from-swift-network-new-rdif-currency-restrictions", "label": "Kelley Drye, EU removes 7 Russian banks from SWIFT, Mar 2022"}, {"url": "https://swift.com/about-us/who-we-are", "label": "Swift, Who we are"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about CIPS. Tap it.", "statements": ["CIPS launched in October 2015.", "Its cross-border payments grew 43% in 2024.", "It is headquartered in Belgium under EU law."], "fakeIndex": 2, "explanation": "That describes Swift. CIPS is China's system, governed by a different rulebook."}, "numbers": {"kind": "numberSense", "prompt": "How many trillion yuan of cross-border payments did CIPS handle in 2024?", "min": 0, "max": 400, "value": 175, "unit": "T", "explanation": "About 175 trillion yuan, up 43% from 2023."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing on a global bank's sanctions team. They ask why CIPS matters.", "prompt": "What's your best answer?", "options": ["It only handles domestic payments", "It is a cross-border route under Chinese rules", "It is part of Swift and run from Belgium"], "correctIndex": 1, "consequences": ["CIPS is built for cross-border yuan payments.", "Different rulebook, different power over who is cut off.", "Swift is Belgian; CIPS is Chinese."], "explanation": "Who governs a network decides who can be cut off. CIPS answers to China, not the EU."}, "proReasoning": "Sanctions people ask which jurisdiction governs each payment route. That decides who can close it.", "commonMistake": "Treating all payment networks as neutral pipes.", "mentalModel": "Ask whose rules govern the route."}, "invest": {"call": {"kind": "theCall", "situation": "A company's Asian suppliers start asking to be paid through CIPS.", "prompt": "What do you weigh?", "options": ["Whether CIPS has a nicer app", "Nothing, since all routes are the same", "How politics could split its payment routes"], "correctIndex": 2, "consequences": ["Interfaces matter less than jurisdiction.", "Routes differ in who can close them.", "Routes governed by rival powers can diverge."], "explanation": "Payment routes carry political exposure. Know which ones a business depends on."}, "proReasoning": "Investors map a firm's payment routes to the governments behind them. Politics can close a route in days.", "commonMistake": "Ignoring which jurisdiction governs a company's cash flows.", "mentalModel": "Routes carry politics."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your trade-finance startup serves firms that buy from China.", "prompt": "What does CIPS growth mean for you?", "options": ["Support yuan routes alongside existing ones", "Ignore it, since growth will stop soon", "Drop all other payment routes now"], "correctIndex": 0, "consequences": ["Clients may need both, depending on counterparties.", "It grew 43% in 2024.", "Most clients still need existing routes too."], "explanation": "A fast-growing route your clients' suppliers use is one to support, without dropping the rest."}, "proReasoning": "Founders support the routes their customers' counterparties use. More routes mean more resilience.", "commonMistake": "Betting everything on a single payment route.", "mentalModel": "Support the routes counterparties use."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what CIPS is.", "prompt": "What's the best answer?", "options": ["A cryptocurrency China launched in 2015", "China's system for cross-border yuan payments", "China's version of a credit card"], "correctIndex": 1, "consequences": ["It moves yuan between banks; it is not a coin.", "It handled 175 trillion yuan in 2024.", "It links banks, not shoppers."], "explanation": "CIPS is an interbank system for yuan payments across borders, reaching 185 countries and regions."}, "proReasoning": "Explain CIPS by what it connects: banks, across borders, in yuan.", "commonMistake": "Confusing interbank systems with consumer products.", "mentalModel": "Say what it connects."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$dc6ebf11-4710-51c3-8704-b1cc6864e9e0$ml$::uuid, $ml$fintech$ml$, 12, 2, $ml${"id": "fintech-d12-c2", "title": "A messenger with real power", "lessonTitle": "Cut off from Swift", "slot": 2, "type": "connect", "brief": {"headline": "Swift moves no money; it only carries payment messages. Yet in March 2022, cutting seven Russian banks off it made their cross-border payments far harder.", "kicker": "Connect day 7 and day 12: a message network can still cut you off.", "fullText": "On day 7 you learned that Swift carries payment instructions between over 12,500 institutions, while banks move the money. On day 12 you saw that this makes it a lever. The EU ordered Bank Otkritie, Novikombank, Promsvyazbank, Bank Rossiya, Sovcombank, VEB and VTB removed from Swift, effective March 12, 2022.\n\nWithout the standard way to send instructions, cross-border payments get far harder. Swift is subject to EU law, so the EU could order it.", "sources": [{"url": "https://swift.com/about-us/who-we-are", "label": "Swift, Who we are"}, {"url": "https://www.kelleydrye.com/viewpoints/blogs/trade-and-manufacturing-monitor/eu-imposes-measure-to-remove-7-russian-banks-from-swift-network-new-rdif-currency-restrictions", "label": "Kelley Drye, EU removes 7 Russian banks from SWIFT, Mar 2022"}]}, "evidence": {"kind": "multipleChoice", "prompt": "If Swift moves no money, why does a cutoff hurt a bank?", "options": ["Swift seizes the money the bank holds", "Swift closes the bank's branches", "Banks rely on its messages to send payments"], "correctIndex": 2, "explanation": "The messages are how banks instruct each other. Lose them, and cross-border payments stall."}, "numbers": {"kind": "numberSense", "prompt": "Swift links institutions in more than how many countries and territories?", "min": 0, "max": 500, "value": 220, "explanation": "More than 220. Being cut off means losing easy contact with most of the world."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In a sanctions interview, you're asked how a messaging cutoff hurts a bank.", "prompt": "What's your best answer?", "options": ["Its deposits are seized by Swift at once", "Its staff can no longer send emails", "It loses the standard way to send payments"], "correctIndex": 2, "consequences": ["Swift holds no deposits.", "It is about payment messages, not email.", "Instructions are the first step of every payment."], "explanation": "Payments start with an instruction. Cut the instruction channel, and payments stall."}, "proReasoning": "Explain the cutoff through the payment chain: no message, no payment. It shows you know the plumbing.", "commonMistake": "Thinking Swift holds money it can freeze.", "mentalModel": "No message, no payment."}, "invest": {"call": {"kind": "theCall", "situation": "A bank earns much of its income from cross-border payments sent over Swift.", "prompt": "What risk do you check?", "options": ["Whether politics could cut its access", "Whether Swift raises its logo fee", "Whether its app needs a redesign"], "correctIndex": 0, "consequences": ["Banks lost access within ten days in 2022.", "Fees are minor next to losing access.", "Design does not decide access."], "explanation": "Access to Swift can be withdrawn by law. Cross-border income depends on it."}, "proReasoning": "Investors treat network access as a political exposure, not a given.", "commonMistake": "Assuming access to the messaging network is permanent.", "mentalModel": "Access can be withdrawn."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build payment messaging software for banks.", "prompt": "What did 2022 show about your product?", "options": ["Banks can skip messages entirely", "Messages are critical infrastructure", "Messages matter less than money"], "correctIndex": 1, "consequences": ["Every payment starts with an instruction.", "Cutting messages stalled payments for seven banks.", "Without messages, money does not move."], "explanation": "The cutoff proved messaging is not a side detail. It is how payments begin."}, "proReasoning": "Founders in messaging can point to 2022 to show why their layer is critical.", "commonMistake": "Underselling the messaging layer as mere plumbing.", "mentalModel": "The message layer is critical."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how blocking messages can hurt a bank.", "prompt": "What's the best answer?", "options": ["The messages are made of money", "Swift owns all the banks it serves", "Banks can't tell each other to pay"], "correctIndex": 2, "consequences": ["Messages carry instructions, not funds.", "Swift is a cooperative, not an owner.", "Instructions come before every transfer."], "explanation": "Banks need messages to instruct transfers. Block the messages and the transfers get stuck."}, "proReasoning": "Explain payments as instructions plus money. Cut either one, and nothing moves.", "commonMistake": "Thinking only money transfers matter.", "mentalModel": "Instructions come first."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$9711b836-5b34-5aa5-b73f-e8c421360c38$ml$::uuid, $ml$fintech$ml$, 12, 3, $ml${"id": "fintech-d12-c3", "title": "Ten days to the cutoff", "lessonTitle": "Cut off from Swift", "slot": 3, "type": "decide", "brief": {"headline": "On March 2, 2022, the EU ordered seven Russian banks off Swift, effective March 12. You run treasury at an EU company with open invoices paid through one of them.", "kicker": "Decide what to do with the days before a cutoff.", "fullText": "The seven banks, including VTB, Bank Rossiya and Sovcombank, were already under Western asset freezes. Swift, a cooperative headquartered in Belgium, is subject to EU law, so it had to comply. The order gave ten days before the cutoff took effect.\n\nIn payments, whoever controls the messaging network can cut a bank off. Your company has open invoices that a customer pays through one of the named banks.", "sources": [{"url": "https://www.kelleydrye.com/viewpoints/blogs/trade-and-manufacturing-monitor/eu-imposes-measure-to-remove-7-russian-banks-from-swift-network-new-rdif-currency-restrictions", "label": "Kelley Drye, EU removes 7 Russian banks from SWIFT, Mar 2022"}, {"url": "https://swift.com/about-us/who-we-are", "label": "Swift, Who we are"}]}, "evidence": {"kind": "faceOff", "prompt": "Which body could order Swift to cut off the Russian banks?", "left": {"name": "The European Union", "note": "Swift is based in Belgium"}, "right": {"name": "Swift members by vote", "note": "Swift is a cooperative"}, "correctIndex": 0, "explanation": "Swift is subject to EU law because it is headquartered in Belgium. The EU ordered the cutoff."}, "numbers": {"kind": "numberSense", "prompt": "How many days passed between the EU's order and the cutoff?", "min": 0, "max": 30, "value": 10, "unit": "days", "explanation": "Ten days, from March 2 to March 12, 2022."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a compliance analyst on March 2, 2022. Your company has customers paying through the named banks.", "prompt": "What do you do first?", "options": ["List every flow that touches those banks", "Wait for the cutoff to see what breaks", "Assume nothing changes for your firm"], "correctIndex": 0, "consequences": ["You can only act on exposure you have mapped.", "Ten days is short; waiting wastes them.", "Seven banks lost Swift access; flows will break."], "explanation": "Map the exposure first. Every later decision depends on knowing which payments are affected."}, "proReasoning": "Compliance analysts map exposure the day an order lands. The deadline is the reason to start now.", "commonMistake": "Waiting for the cutoff to reveal the exposure.", "mentalModel": "Map exposure on day one."}, "invest": {"call": {"kind": "theCall", "situation": "A European exporter earns a large share of revenue from customers using the named banks.", "prompt": "What do you expect?", "options": ["No effect, since goods still ship", "Collections from those customers get harder", "Faster payment from those same customers"], "correctIndex": 1, "consequences": ["Shipping goods is not the same as being paid.", "Without Swift, their payments get far harder.", "Cutoffs slow payments; they do not speed them."], "explanation": "If customers cannot send payments easily, the exporter's cash collection suffers."}, "proReasoning": "Investors trace sanctions to cash collection. Revenue booked is not cash received.", "commonMistake": "Assuming sales hold up when customers cannot pay.", "mentalModel": "Sanctions hit collections."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run treasury at the EU company. Open invoices are paid through one of the named banks.", "prompt": "What do you do with the ten days?", "options": ["Ship more goods on credit to that customer", "Do nothing and hope for an exemption", "Settle open invoices lawfully before it hits"], "correctIndex": 2, "consequences": ["More credit adds to what may never arrive.", "Hope is not a treasury plan.", "Settled money is final before access ends."], "explanation": "Use the window to settle what you lawfully can. After the cutoff, collecting gets far harder."}, "proReasoning": "Treasury leads use deadlines to turn promises into settled money, within the law.", "commonMistake": "Extending more credit into a closing window.", "mentalModel": "Settle before the door closes."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Swift obeyed the EU instead of its member banks.", "prompt": "What's the best answer?", "options": ["It's based in Belgium, bound by EU law", "The EU owns Swift outright as a company", "Swift members voted for it"], "correctIndex": 0, "consequences": ["Headquarters set which law applies.", "Swift is a cooperative, not EU property.", "The order came from EU law, not a vote."], "explanation": "Swift is headquartered in Belgium, so EU law binds it."}, "proReasoning": "Where a network is based decides whose laws it follows. That is where its political risk comes from.", "commonMistake": "Thinking a cooperative answers only to its members.", "mentalModel": "Location decides the law."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[])
